import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import L from 'leaflet';
import 'leaflet/dist/leaflet.css';
import './styles.css';

const FEEDS = {
  hour: { label: 'Past hour', shortLabel: '1h', durationMs: 60 * 60 * 1000, path: 'all_hour.geojson' },
  day: { label: 'Past day', shortLabel: '24h', durationMs: 24 * 60 * 60 * 1000, path: 'all_day.geojson' },
  week: { label: 'Past 7 days', shortLabel: '7d', durationMs: 7 * 24 * 60 * 60 * 1000, path: 'all_week.geojson' },
  month: { label: 'Past 30 days', shortLabel: '30d', durationMs: 30 * 24 * 60 * 60 * 1000, path: 'all_month.geojson' },
};

const USGS_FEED_ROOT = 'https://earthquake.usgs.gov/earthquakes/feed/v1.0/summary/';
const MAX_DEPTH = 700;
const DEFAULTS = {
  timeframe: 'week',
  minMag: 0,
  maxMag: 9,
  depthMin: 0,
  depthMax: MAX_DEPTH,
  alert: 'all',
  tsunamiOnly: false,
  reviewedOnly: false,
  placeQuery: '',
  sort: 'time',
};

function readInitialState() {
  const params = new URLSearchParams(window.location.search);
  const timeframe = params.get('range');
  const minMag = Number(params.get('minMag'));
  const maxMag = Number(params.get('maxMag'));
  const depthMin = Number(params.get('depthMin'));
  const depthMax = Number(params.get('depthMax'));
  return {
    timeframe: timeframe && FEEDS[timeframe] ? timeframe : DEFAULTS.timeframe,
    minMag: Number.isFinite(minMag) ? Math.max(0, Math.min(9, minMag)) : DEFAULTS.minMag,
    maxMag: Number.isFinite(maxMag) ? Math.max(0, Math.min(9, maxMag)) : DEFAULTS.maxMag,
    depthMin: Number.isFinite(depthMin) ? Math.max(0, Math.min(MAX_DEPTH, depthMin)) : DEFAULTS.depthMin,
    depthMax: Number.isFinite(depthMax) ? Math.max(0, Math.min(MAX_DEPTH, depthMax)) : DEFAULTS.depthMax,
    alert: ['all', 'green', 'yellow', 'orange', 'red', 'unknown'].includes(params.get('alert')) ? params.get('alert') : DEFAULTS.alert,
    tsunamiOnly: params.get('tsunami') === '1',
    reviewedOnly: params.get('reviewed') === '1',
    placeQuery: params.get('place') || DEFAULTS.placeQuery,
    sort: ['time', 'magnitude', 'depth'].includes(params.get('sort')) ? params.get('sort') : DEFAULTS.sort,
    selectedEventId: params.get('event') || '',
  };
}

function normalizeFeature(feature, index) {
  const properties = feature?.properties || {};
  const coordinates = feature?.geometry?.coordinates || [];
  const longitude = Number(coordinates[0]);
  const latitude = Number(coordinates[1]);
  const depth = Number(coordinates[2]);
  const time = Number(properties.time);
  if (!Number.isFinite(latitude) || !Number.isFinite(longitude) || !Number.isFinite(time)) return null;
  const magnitude = Number(properties.mag);
  const significance = Number(properties.sig);
  const felt = Number(properties.felt);
  return {
    id: String(properties.code || feature.id || `event-${time}-${index}`),
    magnitude: Number.isFinite(magnitude) ? magnitude : null,
    place: properties.place || 'Location not reported',
    title: properties.title || properties.place || 'Earthquake',
    time,
    updated: Number(properties.updated) || null,
    latitude,
    longitude,
    depth: Number.isFinite(depth) ? depth : null,
    felt: Number.isFinite(felt) ? felt : null,
    significance: Number.isFinite(significance) ? significance : null,
    alert: properties.alert || null,
    tsunami: properties.tsunami === 1 || properties.tsunami === '1',
    status: properties.status || null,
    eventType: properties.type || null,
    url: properties.url || null,
    detail: properties.detail || null,
    network: properties.net || null,
  };
}

function formatNumber(value) {
  return new Intl.NumberFormat('en-US').format(value);
}

function formatMagnitude(value) {
  return Number.isFinite(value) ? value.toFixed(1) : '—';
}

function formatDepth(value) {
  return Number.isFinite(value) ? `${value.toFixed(value < 10 ? 1 : 0)} km` : 'Depth not reported';
}

function formatRelativeTime(timestamp, now = Date.now()) {
  if (!Number.isFinite(timestamp)) return 'Time not reported';
  const seconds = Math.max(0, Math.round((now - timestamp) / 1000));
  if (seconds < 60) return 'just now';
  if (seconds < 3600) return `${Math.floor(seconds / 60)}m ago`;
  if (seconds < 86400) return `${Math.floor(seconds / 3600)}h ago`;
  return `${Math.floor(seconds / 86400)}d ago`;
}

function formatLocalTime(timestamp) {
  if (!Number.isFinite(timestamp)) return 'Time not reported';
  return new Intl.DateTimeFormat(undefined, {
    dateStyle: 'medium',
    timeStyle: 'short',
  }).format(new Date(timestamp));
}

function formatUtcTime(timestamp) {
  if (!Number.isFinite(timestamp)) return 'Time not reported';
  return new Intl.DateTimeFormat('en-GB', {
    dateStyle: 'medium',
    timeStyle: 'short',
    timeZone: 'UTC',
    timeZoneName: 'short',
  }).format(new Date(timestamp));
}

function formatAge(timestamp, now = Date.now()) {
  if (!timestamp) return 'Not refreshed yet';
  const seconds = Math.max(0, Math.floor((now - timestamp) / 1000));
  if (seconds < 60) return 'refreshed just now';
  if (seconds < 3600) return `refreshed ${Math.floor(seconds / 60)}m ago`;
  return `refreshed ${Math.floor(seconds / 3600)}h ago`;
}

function formatWindow(start, end) {
  if (!start || !end) return '';
  const sameDay = new Date(start).toDateString() === new Date(end).toDateString();
  const startText = new Intl.DateTimeFormat(undefined, { month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit' }).format(new Date(start));
  const endText = new Intl.DateTimeFormat(undefined, sameDay ? { hour: 'numeric', minute: '2-digit' } : { month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit' }).format(new Date(end));
  return `${startText} – ${endText}`;
}

function formatBucketLabel(timestamp, timeframe) {
  const options = timeframe === 'month'
    ? { month: 'short', day: 'numeric' }
    : timeframe === 'week'
      ? { weekday: 'short', hour: 'numeric' }
      : { hour: 'numeric', minute: '2-digit' };
  return new Intl.DateTimeFormat(undefined, options).format(new Date(timestamp));
}

function getAlertLabel(alert) {
  return alert ? `${alert[0].toUpperCase()}${alert.slice(1)} alert` : 'No alert level';
}

function getAlertClass(alert) {
  return alert ? `alert-${alert}` : 'alert-unknown';
}

function colorForMagnitude(magnitude) {
  if (!Number.isFinite(magnitude)) return '#71817e';
  if (magnitude < 2) return '#8ba6a0';
  if (magnitude < 4) return '#bb9860';
  if (magnitude < 5) return '#c46f4d';
  return '#ad4037';
}

function App() {
  const initialState = useMemo(() => readInitialState(), []);
  const [timeframe, setTimeframe] = useState(initialState.timeframe);
  const [minMag, setMinMag] = useState(initialState.minMag);
  const [maxMag, setMaxMag] = useState(Math.max(initialState.maxMag, initialState.minMag));
  const [depthMin, setDepthMin] = useState(Math.min(initialState.depthMin, initialState.depthMax));
  const [depthMax, setDepthMax] = useState(Math.max(initialState.depthMax, initialState.depthMin));
  const [alert, setAlert] = useState(initialState.alert);
  const [tsunamiOnly, setTsunamiOnly] = useState(initialState.tsunamiOnly);
  const [reviewedOnly, setReviewedOnly] = useState(initialState.reviewedOnly);
  const [placeQuery, setPlaceQuery] = useState(initialState.placeQuery);
  const [sort, setSort] = useState(initialState.sort);
  const [events, setEvents] = useState([]);
  const [loadState, setLoadState] = useState('loading');
  const [error, setError] = useState('');
  const [lastUpdated, setLastUpdated] = useState(null);
  const [nowTick, setNowTick] = useState(Date.now());
  const [selectedEventId, setSelectedEventId] = useState(initialState.selectedEventId);
  const [hoveredEventId, setHoveredEventId] = useState('');
  const [timelineWindow, setTimelineWindow] = useState(null);
  const [activeTooltip, setActiveTooltip] = useState(null);
  const [streamLimit, setStreamLimit] = useState(160);
  const [shareState, setShareState] = useState('');
  const [geocodeState, setGeocodeState] = useState({ status: 'idle', label: '' });
  const [mapZoom, setMapZoom] = useState(2);

  const mapContainerRef = useRef(null);
  const mapInstanceRef = useRef(null);
  const markerLayerRef = useRef(null);
  const abortControllerRef = useRef(null);
  const eventsRef = useRef(events);
  const detailRef = useRef(null);

  useEffect(() => {
    eventsRef.current = events;
  }, [events]);

  useEffect(() => {
    const interval = window.setInterval(() => setNowTick(Date.now()), 60 * 1000);
    return () => window.clearInterval(interval);
  }, []);

  const loadFeed = useCallback(async (range) => {
    if (abortControllerRef.current) abortControllerRef.current.abort();
    const controller = new AbortController();
    abortControllerRef.current = controller;
    setLoadState(eventsRef.current.length ? 'refreshing' : 'loading');
    setError('');
    try {
      const response = await fetch(`${USGS_FEED_ROOT}${FEEDS[range].path}?updated=${Date.now()}`, {
        signal: controller.signal,
        headers: { Accept: 'application/geo+json' },
      });
      if (!response.ok) throw new Error(`USGS returned ${response.status}`);
      const payload = await response.json();
      const nextEvents = (Array.isArray(payload.features) ? payload.features : [])
        .map(normalizeFeature)
        .filter(Boolean)
        .sort((a, b) => b.time - a.time);
      setEvents(nextEvents);
      setLastUpdated(Date.now());
      setLoadState('ready');
    } catch (requestError) {
      if (requestError?.name === 'AbortError') return;
      setError('The USGS feed could not be reached. The last displayed data is preserved.');
      setLoadState('error');
    }
  }, []);

  useEffect(() => {
    loadFeed(timeframe);
    const interval = window.setInterval(() => loadFeed(timeframe), 5 * 60 * 1000);
    return () => window.clearInterval(interval);
  }, [loadFeed, timeframe]);

  useEffect(() => () => abortControllerRef.current?.abort(), []);

  useEffect(() => {
    const params = new URLSearchParams();
    params.set('range', timeframe);
    if (minMag > DEFAULTS.minMag) params.set('minMag', String(minMag));
    if (maxMag < DEFAULTS.maxMag) params.set('maxMag', String(maxMag));
    if (depthMin > DEFAULTS.depthMin) params.set('depthMin', String(depthMin));
    if (depthMax < DEFAULTS.depthMax) params.set('depthMax', String(depthMax));
    if (alert !== DEFAULTS.alert) params.set('alert', alert);
    if (tsunamiOnly) params.set('tsunami', '1');
    if (reviewedOnly) params.set('reviewed', '1');
    if (placeQuery) params.set('place', placeQuery);
    if (sort !== DEFAULTS.sort) params.set('sort', sort);
    if (selectedEventId) params.set('event', selectedEventId);
    if (timelineWindow) {
      params.set('from', String(timelineWindow.start));
      params.set('to', String(timelineWindow.end));
    }
    const nextSearch = `?${params.toString()}`;
    if (window.location.search !== nextSearch) window.history.replaceState({}, '', `${window.location.pathname}${nextSearch}${window.location.hash}`);
  }, [timeframe, minMag, maxMag, depthMin, depthMax, alert, tsunamiOnly, reviewedOnly, placeQuery, sort, selectedEventId, timelineWindow]);

  const filteredEvents = useMemo(() => events.filter((event) => {
    const placeMatch = !placeQuery || event.place.toLowerCase().includes(placeQuery.trim().toLowerCase());
    const magMatch = (event.magnitude === null || (event.magnitude >= minMag && event.magnitude <= maxMag));
    const depthMatch = event.depth === null || (event.depth >= depthMin && event.depth <= depthMax);
    const alertMatch = alert === 'all' || (alert === 'unknown' ? !event.alert : event.alert === alert);
    const tsunamiMatch = !tsunamiOnly || event.tsunami;
    const reviewedMatch = !reviewedOnly || event.status === 'reviewed';
    return placeMatch && magMatch && depthMatch && alertMatch && tsunamiMatch && reviewedMatch;
  }), [events, placeQuery, minMag, maxMag, depthMin, depthMax, alert, tsunamiOnly, reviewedOnly]);

  const sortedEvents = useMemo(() => [...filteredEvents].sort((a, b) => {
    if (sort === 'magnitude') return (b.magnitude ?? -Infinity) - (a.magnitude ?? -Infinity) || b.time - a.time;
    if (sort === 'depth') return (a.depth ?? Infinity) - (b.depth ?? Infinity) || b.time - a.time;
    return b.time - a.time;
  }), [filteredEvents, sort]);

  const strongestEvent = useMemo(() => [...filteredEvents].sort((a, b) => (b.magnitude ?? -Infinity) - (a.magnitude ?? -Infinity) || b.time - a.time)[0] || null, [filteredEvents]);
  const selectedEvent = useMemo(() => filteredEvents.find((event) => event.id === selectedEventId) || strongestEvent, [filteredEvents, selectedEventId, strongestEvent]);

  useEffect(() => {
    if (!selectedEventId && strongestEvent) setSelectedEventId(strongestEvent.id);
  }, [selectedEventId, strongestEvent]);

  const timelineBuckets = useMemo(() => {
    const range = FEEDS[timeframe];
    const bucketCount = timeframe === 'hour' ? 12 : timeframe === 'day' ? 24 : timeframe === 'week' ? 28 : 30;
    const end = nowTick;
    const start = end - range.durationMs;
    const bucketDuration = range.durationMs / bucketCount;
    return Array.from({ length: bucketCount }, (_, index) => {
      const bucketStart = start + index * bucketDuration;
      const bucketEnd = bucketStart + bucketDuration;
      const bucketEvents = filteredEvents.filter((event) => event.time >= bucketStart && event.time < bucketEnd);
      return {
        index,
        start: bucketStart,
        end: bucketEnd,
        events: bucketEvents,
        count: bucketEvents.length,
        maxMagnitude: Math.max(...bucketEvents.map((event) => event.magnitude ?? 0), 0),
      };
    });
  }, [filteredEvents, nowTick, timeframe]);

  const selectedBucketIndex = useMemo(() => selectedEvent ? timelineBuckets.findIndex((bucket) => selectedEvent.time >= bucket.start && selectedEvent.time < bucket.end) : -1, [selectedEvent, timelineBuckets]);
  const timelineWindowEvents = timelineWindow ? filteredEvents.filter((event) => event.time >= timelineWindow.start && event.time < timelineWindow.end) : [];
  const maxTimelineCount = Math.max(...timelineBuckets.map((bucket) => bucket.count), 1);

  const depthBuckets = useMemo(() => {
    const bands = [
      { label: 'Shallow', sublabel: '0–20 km', min: 0, max: 20 },
      { label: 'Crustal', sublabel: '20–70 km', min: 20, max: 70 },
      { label: 'Intermediate', sublabel: '70–300 km', min: 70, max: 300 },
      { label: 'Deep', sublabel: '300+ km', min: 300, max: MAX_DEPTH },
    ];
    return bands.map((band) => ({
      ...band,
      count: filteredEvents.filter((event) => event.depth !== null && event.depth >= band.min && (band.max === MAX_DEPTH ? event.depth <= MAX_DEPTH : event.depth < band.max)).length,
    }));
  }, [filteredEvents]);
  const maxDepthCount = Math.max(...depthBuckets.map((band) => band.count), 1);

  const selectEvent = useCallback((event, shouldScroll = true) => {
    setSelectedEventId(event.id);
    if (shouldScroll && window.innerWidth < 980) {
      window.requestAnimationFrame(() => detailRef.current?.scrollIntoView({ behavior: window.matchMedia('(prefers-reduced-motion: reduce)').matches ? 'auto' : 'smooth', block: 'start' }));
    }
  }, []);

  const focusEventOnMap = useCallback((event) => {
    selectEvent(event, false);
    mapInstanceRef.current?.panTo([event.latitude, event.longitude], { animate: !window.matchMedia('(prefers-reduced-motion: reduce)').matches });
  }, [selectEvent]);

  const resetFilters = useCallback(() => {
    setMinMag(DEFAULTS.minMag);
    setMaxMag(DEFAULTS.maxMag);
    setDepthMin(DEFAULTS.depthMin);
    setDepthMax(DEFAULTS.depthMax);
    setAlert(DEFAULTS.alert);
    setTsunamiOnly(DEFAULTS.tsunamiOnly);
    setReviewedOnly(DEFAULTS.reviewedOnly);
    setPlaceQuery(DEFAULTS.placeQuery);
    setSort(DEFAULTS.sort);
    setTimelineWindow(null);
    setSelectedEventId('');
    setStreamLimit(160);
  }, []);

  const copyShareLink = useCallback(async () => {
    const url = window.location.href;
    try {
      if (!navigator.clipboard) throw new Error('Clipboard unavailable');
      await navigator.clipboard.writeText(url);
      setShareState('Link copied');
    } catch {
      window.prompt('Copy this observatory link', url);
      setShareState('Link ready to copy');
    }
    window.setTimeout(() => setShareState(''), 2500);
  }, []);

  const geocodePlace = useCallback(async (event) => {
    event?.preventDefault();
    const query = placeQuery.trim();
    if (!query) {
      setGeocodeState({ status: 'idle', label: '' });
      return;
    }
    setGeocodeState({ status: 'loading', label: '' });
    try {
      const response = await fetch(`https://nominatim.openstreetmap.org/search?format=jsonv2&limit=1&q=${encodeURIComponent(query)}`, {
        headers: { Accept: 'application/json' },
      });
      if (!response.ok) throw new Error('Geocoder unavailable');
      const results = await response.json();
      const result = results?.[0];
      if (!result) throw new Error('Place not found');
      const latitude = Number(result.lat);
      const longitude = Number(result.lon);
      mapInstanceRef.current?.setView([latitude, longitude], Math.max(mapInstanceRef.current.getZoom(), 5), { animate: !window.matchMedia('(prefers-reduced-motion: reduce)').matches });
      setGeocodeState({ status: 'ready', label: result.display_name });
    } catch {
      setGeocodeState({ status: 'error', label: 'Place not found. Try a country, city, or region.' });
    }
  }, [placeQuery]);

  useEffect(() => {
    if (mapInstanceRef.current || !mapContainerRef.current) return undefined;
    const map = L.map(mapContainerRef.current, {
      center: [18, 0],
      zoom: 2,
      minZoom: 2,
      maxZoom: 9,
      worldCopyJump: true,
      zoomControl: false,
      attributionControl: true,
    });
    L.tileLayer('https://{s}.basemaps.cartocdn.com/light_all/{z}/{x}/{y}{r}.png', {
      maxZoom: 20,
      attribution: '&copy; OpenStreetMap contributors &copy; CARTO',
      subdomains: 'abcd',
    }).addTo(map);
    L.control.zoom({ position: 'bottomright' }).addTo(map);
    markerLayerRef.current = L.layerGroup().addTo(map);
    mapInstanceRef.current = map;
    setMapZoom(map.getZoom());
    const handleResize = () => map.invalidateSize();
    const handleZoom = () => setMapZoom(map.getZoom());
    window.addEventListener('resize', handleResize);
    map.on('zoomend', handleZoom);
    window.setTimeout(() => map.invalidateSize(), 0);
    return () => {
      window.removeEventListener('resize', handleResize);
      map.remove();
      mapInstanceRef.current = null;
      markerLayerRef.current = null;
    };
  }, []);

  useEffect(() => {
    const map = mapInstanceRef.current;
    const layer = markerLayerRef.current;
    if (!map || !layer) return;
    layer.clearLayers();
    const clusterSize = mapZoom <= 2 ? 18 : mapZoom <= 3 ? 8 : mapZoom <= 4 ? 4 : mapZoom <= 5 ? 1.5 : 0;
    const groups = new Map();
    filteredEvents.forEach((event) => {
      const key = clusterSize ? `${Math.floor((event.latitude + 90) / clusterSize)}:${Math.floor((event.longitude + 180) / clusterSize)}` : event.id;
      if (!groups.has(key)) groups.set(key, []);
      groups.get(key).push(event);
    });

    groups.forEach((group) => {
      if (group.length > 1) {
        const latitude = group.reduce((sum, event) => sum + event.latitude, 0) / group.length;
        const longitude = group.reduce((sum, event) => sum + event.longitude, 0) / group.length;
        const maxMagnitude = Math.max(...group.map((event) => event.magnitude ?? 0));
        const inTimeline = !timelineWindow || group.some((event) => event.time >= timelineWindow.start && event.time < timelineWindow.end);
        const icon = L.divIcon({
          className: 'quake-cluster-icon',
          html: `<span class="quake-cluster ${maxMagnitude >= 5 ? 'quake-cluster-large' : ''} ${inTimeline ? '' : 'quake-marker-muted'}"><b>${group.length}</b><small>M${formatMagnitude(maxMagnitude)}</small></span>`,
          iconSize: [56, 56],
          iconAnchor: [28, 28],
        });
        const marker = L.marker([latitude, longitude], { icon, keyboard: true, title: `${group.length} earthquakes in this area` });
        marker.bindTooltip(`${group.length} events · strongest M${formatMagnitude(maxMagnitude)}`, { direction: 'top', offset: [0, -26] });
        const bounds = L.latLngBounds(group.map((event) => [event.latitude, event.longitude]));
        marker.on('click', () => {
          if (bounds.isValid() && bounds.getNorthEast().equals(bounds.getSouthWest())) map.setView([latitude, longitude], Math.min(map.getZoom() + 2, 9));
          else map.fitBounds(bounds.pad(0.18), { maxZoom: Math.min(map.getZoom() + 3, 8) });
        });
        layer.addLayer(marker);
        return;
      }
      const event = group[0];
      const inTimeline = !timelineWindow || (event.time >= timelineWindow.start && event.time < timelineWindow.end);
      const isFocused = event.id === selectedEvent?.id || event.id === hoveredEventId;
      const alertStroke = event.alert === 'red' ? '#9d3030' : event.alert === 'orange' ? '#b56335' : event.alert === 'yellow' ? '#a77b31' : '#203538';
      const marker = L.circleMarker([event.latitude, event.longitude], {
        radius: Math.max(4, 4 + (event.magnitude ?? 0) * 1.4),
        fillColor: colorForMagnitude(event.magnitude),
        color: isFocused ? '#17252a' : alertStroke,
        weight: isFocused ? 3 : event.tsunami ? 3 : 1.5,
        opacity: inTimeline ? 1 : 0.2,
        fillOpacity: inTimeline ? (isFocused ? 0.98 : 0.78) : 0.12,
        dashArray: event.tsunami ? '4 3' : undefined,
      });
      marker.bindTooltip(`M${formatMagnitude(event.magnitude)} · ${event.place} · ${formatDepth(event.depth)}`, { direction: 'top', offset: [0, -8] });
      marker.on('click', () => selectEvent(event, false));
      marker.on('mouseover', () => setHoveredEventId(event.id));
      marker.on('mouseout', () => setHoveredEventId(''));
      marker.on('focus', () => setHoveredEventId(event.id));
      marker.on('blur', () => setHoveredEventId(''));
      if (isFocused) marker.bringToFront();
      layer.addLayer(marker);
    });
  }, [filteredEvents, hoveredEventId, mapZoom, selectEvent, selectedEvent?.id, timelineWindow]);

  const filterChips = [
    minMag > 0 ? { label: `M ≥ ${minMag.toFixed(1)}`, clear: () => setMinMag(0) } : null,
    maxMag < 9 ? { label: `M ≤ ${maxMag.toFixed(1)}`, clear: () => setMaxMag(9) } : null,
    depthMin > 0 || depthMax < MAX_DEPTH ? { label: `${depthMin}–${depthMax === MAX_DEPTH ? '700+' : depthMax} km`, clear: () => { setDepthMin(0); setDepthMax(MAX_DEPTH); } } : null,
    alert !== 'all' ? { label: getAlertLabel(alert), clear: () => setAlert('all') } : null,
    tsunamiOnly ? { label: 'Tsunami flag', clear: () => setTsunamiOnly(false) } : null,
    reviewedOnly ? { label: 'Reviewed origins', clear: () => setReviewedOnly(false) } : null,
    placeQuery ? { label: `Place: ${placeQuery}`, clear: () => { setPlaceQuery(''); setGeocodeState({ status: 'idle', label: '' }); } } : null,
  ].filter(Boolean);

  const eventIsInWindow = (event) => !timelineWindow || (event.time >= timelineWindow.start && event.time < timelineWindow.end);
  const visibleStreamEvents = sortedEvents.slice(0, streamLimit);
  const dataAge = formatAge(lastUpdated, nowTick);
  const isLoading = loadState === 'loading';
  const isRefreshing = loadState === 'refreshing';
  const isStale = Boolean(lastUpdated && nowTick - lastUpdated > 15 * 60 * 1000);

  return (
    <div className="app-shell">
      <header className="topbar">
        <a className="brand-lockup" href="#top" aria-label="Seismic Observatory home">
          <span className="brand-mark" aria-hidden="true"><i /><i /><i /></span>
          <span>
            <span className="brand-name">Seismic Observatory</span>
            <span className="brand-caption">A live field guide to a moving planet</span>
          </span>
        </a>
        <nav className="topnav" aria-label="Primary navigation">
          <a href="#activity">Activity</a>
          <a href="#stream">Event stream</a>
          <a href="#method">Method</a>
        </nav>
        <div className="top-actions">
          <span className={`connection-status ${isStale || loadState === 'error' ? 'status-stale' : ''}`}>
            <span className="status-dot" aria-hidden="true" />
            {loadState === 'error' ? 'Stale feed' : isRefreshing ? 'Updating' : 'Live feed'}
          </span>
          <button className="button button-dark button-small" type="button" onClick={() => loadFeed(timeframe)} disabled={isLoading || isRefreshing}>
            <span aria-hidden="true">↻</span> Refresh
          </button>
        </div>
      </header>

      <main id="top">
        <section className="intro-band" aria-labelledby="page-title">
          <div>
            <p className="eyebrow">Global seismic field · {FEEDS[timeframe].label}</p>
            <h1 id="page-title">Read the planet in motion.</h1>
            <p className="intro-copy">A calm, live view of where earthquakes are happening, how deep they are, and which signals deserve a closer look.</p>
          </div>
          <div className="intro-note">
            <span className="eyebrow">Data position</span>
            <strong>{dataAge}</strong>
            <span>USGS real-time GeoJSON · times shown in your local zone and UTC</span>
          </div>
        </section>

        <section className="signal-summary" aria-label="Current earthquake summary">
          <div className="summary-count">
            <span className="summary-label">Observed in window</span>
            <strong>{isLoading && events.length === 0 ? '—' : formatNumber(filteredEvents.length)}</strong>
            <span className="summary-subline">{filteredEvents.length === 1 ? 'earthquake matches' : 'earthquakes match'} current view</span>
          </div>
          <div className="summary-divider" aria-hidden="true" />
          <div className="summary-story">
            <span className="summary-label">Strongest signal in view</span>
            {strongestEvent ? (
              <button className="strongest-link" type="button" onClick={() => selectEvent(strongestEvent)}>
                <span className="magnitude-stamp">M{formatMagnitude(strongestEvent.magnitude)}</span>
                <span><b>{strongestEvent.place}</b><small>{formatRelativeTime(strongestEvent.time, nowTick)} · {formatDepth(strongestEvent.depth)}</small></span>
                <span className="arrow-mark" aria-hidden="true">↗</span>
              </button>
            ) : <span className="summary-empty">No event matches the current constraints.</span>}
          </div>
          <div className="summary-legend">
            <span className="summary-label">Reading the map</span>
            <span><i className="legend-dot legend-small" /> radius = magnitude</span>
            <span><i className="legend-ring" /> ring = alert / tsunami flag</span>
          </div>
        </section>

        <section className="control-deck" aria-label="Explore and filter earthquake data">
          <div className="time-rail">
            <span className="control-label">Time window</span>
            <div className="segmented-control" role="group" aria-label="Choose a time window">
              {Object.entries(FEEDS).map(([key, range]) => (
                <button key={key} type="button" className={timeframe === key ? 'is-active' : ''} aria-pressed={timeframe === key} onClick={() => { setTimeframe(key); setTimelineWindow(null); setStreamLimit(160); }}>
                  <span>{range.label}</span><small>{range.shortLabel}</small>
                </button>
              ))}
            </div>
          </div>
          <div className="control-actions">
            <button className="button button-light" type="button" onClick={copyShareLink}><span aria-hidden="true">⌁</span> Share view</button>
            <button className="button button-quiet" type="button" onClick={resetFilters} disabled={!filterChips.length && !timelineWindow}>Reset all</button>
            {shareState && <span className="action-feedback" role="status">{shareState}</span>}
          </div>

          <div className="filter-grid">
            <fieldset className="filter-group magnitude-filter">
              <legend>Magnitude</legend>
              <div className="range-pair">
                <label><span>At least</span><output>M{minMag.toFixed(1)}</output><input type="range" min="0" max="9" step="0.1" value={minMag} onChange={(event) => setMinMag(Math.min(Number(event.target.value), maxMag))} /></label>
                <label><span>At most</span><output>{maxMag >= 9 ? 'Any' : `M${maxMag.toFixed(1)}`}</output><input type="range" min="0" max="9" step="0.1" value={maxMag} onChange={(event) => setMaxMag(Math.max(Number(event.target.value), minMag))} /></label>
              </div>
            </fieldset>
            <fieldset className="filter-group depth-filter">
              <legend>Depth, kilometers</legend>
              <div className="number-pair">
                <label><span>From</span><input type="number" min="0" max={MAX_DEPTH} value={depthMin} onChange={(event) => setDepthMin(Math.min(MAX_DEPTH, Math.max(0, Number(event.target.value) || 0)))} /></label>
                <span className="number-dash" aria-hidden="true">—</span>
                <label><span>To</span><input type="number" min="0" max={MAX_DEPTH} value={depthMax === MAX_DEPTH ? '' : depthMax} placeholder="700+" onChange={(event) => setDepthMax(Math.min(MAX_DEPTH, Math.max(depthMin, Number(event.target.value) || MAX_DEPTH)))} /></label>
              </div>
            </fieldset>
            <label className="select-control"><span>Alert level</span><select value={alert} onChange={(event) => setAlert(event.target.value)}><option value="all">Any alert level</option><option value="green">Green</option><option value="yellow">Yellow</option><option value="orange">Orange</option><option value="red">Red</option><option value="unknown">Not reported</option></select></label>
            <label className="select-control"><span>Sort stream by</span><select value={sort} onChange={(event) => setSort(event.target.value)}><option value="time">Newest first</option><option value="magnitude">Largest first</option><option value="depth">Shallowest first</option></select></label>
            <form className="place-search" onSubmit={geocodePlace}>
              <label htmlFor="place-query">Place or region</label>
              <div className="search-row"><input id="place-query" type="search" value={placeQuery} onChange={(event) => setPlaceQuery(event.target.value)} placeholder="Filter or find a place" /><button type="submit" className="search-button" aria-label="Find place on map">⌕</button></div>
              {geocodeState.status === 'loading' && <small className="field-status">Looking up place…</small>}
              {geocodeState.status === 'ready' && <small className="field-status field-status-good">Map centered on {geocodeState.label}</small>}
              {geocodeState.status === 'error' && <small className="field-status field-status-error">{geocodeState.label}</small>}
            </form>
            <div className="check-control">
              <span className="control-subhead">Signals</span>
              <label><input type="checkbox" checked={tsunamiOnly} onChange={(event) => setTsunamiOnly(event.target.checked)} /> <span>Tsunami flag</span></label>
              <label><input type="checkbox" checked={reviewedOnly} onChange={(event) => setReviewedOnly(event.target.checked)} /> <span>Reviewed origins</span></label>
            </div>
          </div>
          <div className="active-filters" aria-live="polite">
            <span className="active-label">{formatNumber(filteredEvents.length)} of {formatNumber(events.length)} events</span>
            {filterChips.length ? filterChips.map((chip) => <button key={chip.label} type="button" className="filter-chip" onClick={chip.clear}>{chip.label}<span aria-hidden="true">×</span></button>) : <span className="no-filters">All available events shown</span>}
            {timelineWindow && <button className="filter-chip filter-chip-time" type="button" onClick={() => setTimelineWindow(null)}>Timeline · {formatWindow(timelineWindow.start, timelineWindow.end)} ×</button>}
          </div>
        </section>

        <div className="workspace" id="activity">
          <div className="map-column">
            <section className="map-panel" aria-labelledby="map-heading">
              <div className="panel-heading map-heading">
                <div><p className="eyebrow">Geographic field</p><h2 id="map-heading">Where the ground is moving</h2></div>
                <div className="map-heading-actions"><span className="map-zoom">Zoom {mapZoom.toFixed(1)}</span><button type="button" className="icon-button" onClick={() => mapInstanceRef.current?.setView([18, 0], 2)} aria-label="Reset map to world view">◎</button></div>
              </div>
              <div className="map-frame">
                <div ref={mapContainerRef} className="map-container" tabIndex="0" aria-label="Interactive world map of earthquakes. Use the event stream below as a keyboard-accessible alternative." />
                <div className="map-key" aria-label="Map legend">
                  <span><i className="key-swatch key-low" /> smaller magnitude</span>
                  <span><i className="key-swatch key-high" /> larger magnitude</span>
                  <span><i className="key-outline" /> tsunami flag</span>
                </div>
                {(isLoading || isRefreshing) && <div className="map-loading" role="status" aria-live="polite"><span className="loader-line" />{isLoading ? 'Loading live USGS events…' : 'Refreshing without losing your place…'}</div>}
                {error && <div className="map-error" role="alert"><strong>Live update paused</strong><span>{error}</span><button type="button" className="button button-light button-small" onClick={() => loadFeed(timeframe)}>Try again</button></div>}
                {!isLoading && !error && !filteredEvents.length && <div className="map-empty"><span className="empty-glyph" aria-hidden="true">⌁</span><strong>No events match</strong><span>Loosen a filter or reset the view to return to the field.</span><button type="button" className="button button-dark button-small" onClick={resetFilters}>Reset filters</button></div>}
              </div>
              <div className="map-caption"><span>{timelineWindow ? `${formatNumber(timelineWindowEvents.length)} events illuminated in selected time slice` : 'Select a marker, cluster, or event row to follow one signal through every view.'}</span><span className="map-attribution">Basemap © CARTO · Events © USGS</span></div>
            </section>

            <section className="timeline-panel" aria-labelledby="timeline-heading">
              <div className="panel-heading timeline-heading">
                <div><p className="eyebrow">Signature interaction · connected time</p><h2 id="timeline-heading">When the field changed</h2></div>
                <div className="timeline-meta"><span>{timelineWindow ? `${formatNumber(timelineWindowEvents.length)} in slice` : 'Click a band to illuminate its events'}</span>{timelineWindow && <button type="button" className="text-button" onClick={() => setTimelineWindow(null)}>Clear slice</button>}</div>
              </div>
              <div className="timeline-chart-wrap">
                <svg className="timeline-chart" viewBox="0 0 1000 190" role="img" aria-labelledby="timeline-heading timeline-description">
                  <desc id="timeline-description">Activity volume by time bucket. Bar height shows the number of matching earthquakes; the warm cap marks the strongest magnitude in each bucket.</desc>
                  <line x1="42" x2="974" y1="148" y2="148" className="chart-baseline" />
                  <line x1="42" x2="974" y1="96" y2="96" className="chart-gridline" />
                  <line x1="42" x2="974" y1="44" y2="44" className="chart-gridline" />
                  <text x="12" y="151" className="chart-axis-label">0</text>
                  <text x="6" y="99" className="chart-axis-label">{Math.ceil(maxTimelineCount / 2)}</text>
                  <text x="4" y="47" className="chart-axis-label">{maxTimelineCount}</text>
                  {timelineBuckets.map((bucket) => {
                    const x = 46 + bucket.index * (928 / timelineBuckets.length);
                    const barWidth = Math.max(5, 928 / timelineBuckets.length - 4);
                    const height = (bucket.count / maxTimelineCount) * 104;
                    const y = 148 - height;
                    const isSelected = timelineWindow && bucket.start === timelineWindow.start;
                    const isFocused = bucket.index === selectedBucketIndex;
                    return <g key={bucket.start} className="timeline-bar-group">
                      <rect x={x} y="22" width={barWidth} height="126" className={`timeline-hit-area ${isSelected ? 'timeline-hit-selected' : ''}`} tabIndex="0" role="button" aria-label={`${formatBucketLabel(bucket.start, timeframe)}: ${bucket.count} earthquakes, strongest magnitude ${formatMagnitude(bucket.maxMagnitude)}`} onClick={() => setTimelineWindow({ start: bucket.start, end: bucket.end })} onKeyDown={(event) => { if (event.key === 'Enter' || event.key === ' ') { event.preventDefault(); setTimelineWindow({ start: bucket.start, end: bucket.end }); } }} onMouseEnter={() => setActiveTooltip({ index: bucket.index, x: x + barWidth / 2 })} onMouseLeave={() => setActiveTooltip(null)} onFocus={() => setActiveTooltip({ index: bucket.index, x: x + barWidth / 2 })} onBlur={() => setActiveTooltip(null)} />
                      <rect x={x} y={y} width={barWidth} height={Math.max(height, bucket.count ? 3 : 0)} rx="3" className={`timeline-bar ${isSelected ? 'timeline-bar-selected' : ''} ${bucket.count ? '' : 'timeline-bar-empty'}`} />
                      {bucket.count > 0 && <rect x={x} y={Math.max(y, 22)} width={barWidth} height="4" rx="2" className="timeline-cap" />}
                      {isFocused && <line x1={x + barWidth / 2} x2={x + barWidth / 2} y1="16" y2="155" className="timeline-focus-line" />}
                      {(bucket.index === 0 || bucket.index === timelineBuckets.length - 1 || bucket.index === Math.floor(timelineBuckets.length / 2)) && <text x={x + barWidth / 2} y="176" textAnchor="middle" className="chart-x-label">{formatBucketLabel(bucket.start, timeframe)}</text>}
                    </g>;
                  })}
                </svg>
                {activeTooltip && timelineBuckets[activeTooltip.index] && <div className="timeline-tooltip" style={{ left: `${(activeTooltip.x / 1000) * 100}%` }} role="status"><b>{formatBucketLabel(timelineBuckets[activeTooltip.index].start, timeframe)}</b><span>{formatNumber(timelineBuckets[activeTooltip.index].count)} earthquakes · strongest M{formatMagnitude(timelineBuckets[activeTooltip.index].maxMagnitude)}</span></div>}
              </div>
              <div className="timeline-reading"><span className="timeline-reading-key"><i className="timeline-key-volume" /> activity volume</span><span className="timeline-reading-key"><i className="timeline-key-peak" /> highest magnitude in bucket</span><span className="timeline-reading-note">The focused line follows the selected event.</span></div>
            </section>

            <section className="depth-panel" aria-labelledby="depth-heading">
              <div className="panel-heading"><div><p className="eyebrow">Depth distribution</p><h2 id="depth-heading">How far below the surface</h2></div><span className="panel-note">Click a band to filter</span></div>
              <div className="depth-distribution" role="list" aria-label="Earthquake counts by depth band">
                {depthBuckets.map((band) => <button key={band.label} type="button" role="listitem" className={`depth-band ${depthMin === band.min && (band.max === MAX_DEPTH ? depthMax === MAX_DEPTH : depthMax === band.max) ? 'is-active' : ''}`} onClick={() => { setDepthMin(band.min); setDepthMax(band.max); }} aria-label={`${band.label}, ${band.sublabel}, ${band.count} events`}><span className="depth-band-copy"><b>{band.label}</b><small>{band.sublabel}</small></span><span className="depth-track"><i style={{ width: `${Math.max(2, (band.count / maxDepthCount) * 100)}%` }} /></span><strong>{formatNumber(band.count)}</strong></button>)}
              </div>
            </section>

            <section className="stream-panel" id="stream" aria-labelledby="stream-heading">
              <div className="panel-heading stream-heading"><div><p className="eyebrow">Accessible event stream</p><h2 id="stream-heading">Every signal, in order</h2></div><div className="stream-total"><strong>{formatNumber(sortedEvents.length)}</strong><span>matching events</span></div></div>
              {timelineWindow && <div className="stream-context" role="status">Time slice active · matching rows are marked with a warm edge; other rows remain in context.</div>}
              {!visibleStreamEvents.length && !isLoading ? <div className="stream-empty"><strong>No event rows to show.</strong><span>Reset filters to restore the live stream.</span><button type="button" className="button button-light button-small" onClick={resetFilters}>Reset filters</button></div> : <div className="event-list" role="list" aria-label="Earthquake event stream">{visibleStreamEvents.map((event) => {
                const selected = selectedEvent?.id === event.id;
                const inWindow = eventIsInWindow(event);
                return <button key={event.id} type="button" role="listitem" className={`event-row ${selected ? 'is-selected' : ''} ${inWindow ? 'is-in-window' : 'is-out-window'}`} aria-current={selected ? 'true' : undefined} onClick={() => selectEvent(event)} onMouseEnter={() => setHoveredEventId(event.id)} onMouseLeave={() => setHoveredEventId('')} onFocus={() => setHoveredEventId(event.id)} onBlur={() => setHoveredEventId('')}>
                  <span className="event-magnitude">M{formatMagnitude(event.magnitude)}</span>
                  <span className="event-row-main"><strong>{event.place}</strong><span>{formatRelativeTime(event.time, nowTick)} · {formatDepth(event.depth)}</span></span>
                  <span className="event-row-tags">{event.tsunami && <em className="tag tag-tsunami">Tsunami flag</em>}{event.alert && <em className={`tag ${getAlertClass(event.alert)}`}>{event.alert} alert</em>}{event.status === 'reviewed' && <em className="tag tag-reviewed">Reviewed</em>}</span>
                  <span className="event-row-arrow" aria-hidden="true">{selected ? '●' : '→'}</span>
                </button>;
              })}</div>}
              {visibleStreamEvents.length < sortedEvents.length && <button type="button" className="load-more" onClick={() => setStreamLimit((limit) => limit + 160)}>Load 160 more <span>({formatNumber(sortedEvents.length - visibleStreamEvents.length)} remaining)</span></button>}
              <p className="stream-footnote">Map-only insights are repeated here so the complete exploration path works by keyboard and touch.</p>
            </section>
          </div>

          <aside className="inspector" ref={detailRef} aria-labelledby="inspector-heading">
            <div className="inspector-topline"><span className="eyebrow">Focused event dossier</span><span className="dossier-index">{selectedEvent ? '01' : '—'}</span></div>
            {selectedEvent ? <>
              <div className="inspector-title-row"><div><span className="magnitude-hero">M{formatMagnitude(selectedEvent.magnitude)}</span><h2 id="inspector-heading">{selectedEvent.place}</h2></div><span className={`status-seal ${getAlertClass(selectedEvent.alert)}`}><i aria-hidden="true" />{selectedEvent.alert ? selectedEvent.alert : 'No alert'}</span></div>
              <p className="detail-lede">{selectedEvent.title}</p>
              <div className="detail-actions"><button type="button" className="button button-dark" onClick={() => focusEventOnMap(selectedEvent)}>Focus on map <span aria-hidden="true">↗</span></button>{selectedEvent.url && <a className="button button-light" href={selectedEvent.url} target="_blank" rel="noreferrer">Official USGS page <span aria-hidden="true">↗</span></a>}</div>
              <dl className="detail-grid">
                <div><dt>Local time</dt><dd>{formatLocalTime(selectedEvent.time)}</dd><small>Your device time zone</small></div>
                <div><dt>UTC time</dt><dd>{formatUtcTime(selectedEvent.time)}</dd><small>USGS reference clock</small></div>
                <div><dt>Depth</dt><dd>{formatDepth(selectedEvent.depth)}</dd><small>Below surface</small></div>
                <div><dt>Felt reports</dt><dd>{selectedEvent.felt === null ? 'Not reported' : formatNumber(selectedEvent.felt)}</dd><small>Public reports</small></div>
                <div><dt>Significance</dt><dd>{selectedEvent.significance === null ? 'Not reported' : formatNumber(selectedEvent.significance)}</dd><small>USGS index, not a damage score</small></div>
                <div><dt>Review status</dt><dd>{selectedEvent.status ? `${selectedEvent.status[0].toUpperCase()}${selectedEvent.status.slice(1)}` : 'Not reported'}</dd><small>Origin quality state</small></div>
                <div><dt>Tsunami flag</dt><dd>{selectedEvent.tsunami ? 'Yes' : 'No'}</dd><small>Check official page for updates</small></div>
                <div><dt>Coordinates</dt><dd>{selectedEvent.latitude.toFixed(3)}°, {selectedEvent.longitude.toFixed(3)}°</dd><small>{selectedEvent.network ? `Network ${selectedEvent.network}` : 'USGS network'}</small></div>
              </dl>
              <div className="detail-note"><span className="note-symbol" aria-hidden="true">i</span><p><strong>Read magnitude with context.</strong> Magnitude describes the energy released at the source. It does not predict damage, which depends on depth, distance, ground conditions, and many other factors.</p></div>
              <div className="detail-timestamp"><span>Event updated {selectedEvent.updated ? formatUtcTime(selectedEvent.updated) : 'time not reported'}</span><span>Data source: USGS</span></div>
            </> : <div className="inspector-empty"><span className="empty-glyph" aria-hidden="true">⌁</span><h2 id="inspector-heading">Waiting for the field</h2><p>The event dossier will appear when live USGS data arrives.</p></div>}
          </aside>
        </div>
      </main>

      <footer className="footer" id="method">
        <div><span className="brand-name">Seismic Observatory</span><p>Exploration, not emergency alerting. Earthquake data can be revised as seismic networks review new information.</p></div>
        <div className="footer-method"><span className="eyebrow">Method note</span><p>Events are loaded directly from the free USGS real-time GeoJSON feeds. Basemap © CARTO / OpenStreetMap. For authoritative updates, follow the official USGS event page and local authorities.</p></div>
        <span className="footer-mark" aria-hidden="true">⌁</span>
      </footer>
      <div className="sr-only" role="status" aria-live="polite">{isLoading ? 'Loading earthquake data.' : isRefreshing ? 'Refreshing earthquake data.' : `${formatNumber(filteredEvents.length)} earthquake results shown.`}</div>
    </div>
  );
}

export default App;

import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { createRoot } from 'react-dom/client';
import L from 'leaflet';
import 'leaflet/dist/leaflet.css';
import './styles.css';

const FEEDS = {
  hour: { label: 'Past hour', shortLabel: '1h', durationMs: 60 * 60 * 1000, path: 'all_hour.geojson' },
  day: { label: 'Past day', shortLabel: '24h', durationMs: 24 * 60 * 60 * 1000, path: 'all_day.geojson' },
  week: { label: 'Past 7 days', shortLabel: '7d', durationMs: 7 * 24 * 60 * 60 * 1000, path: 'all_week.geojson' },
  month: { label: 'Past 30 days', shortLabel: '30d', durationMs: 30 * 24 * 60 * 60 * 1000, path: 'all_month.geojson' },
};

const USGS_FEED_ROOT = 'https://earthquake.usgs.gov/earthquakes/feed/v1.0/summary/';
const MAX_DEPTH = 700;
const DEFAULTS = {
  timeframe: 'week',
  minMag: 0,
  maxMag: 9,
  depthMin: 0,
  depthMax: MAX_DEPTH,
  alert: 'all',
  tsunamiOnly: false,
  reviewedOnly: false,
  placeQuery: '',
  sort: 'time',
};

function readInitialState() {
  const params = new URLSearchParams(window.location.search);
  const timeframe = params.get('range');
  const minMag = Number(params.get('minMag'));
  const maxMag = Number(params.get('maxMag'));
  const depthMin = Number(params.get('depthMin'));
  const depthMax = Number(params.get('depthMax'));
  return {
    timeframe: timeframe && FEEDS[timeframe] ? timeframe : DEFAULTS.timeframe,
    minMag: Number.isFinite(minMag) ? Math.max(0, Math.min(9, minMag)) : DEFAULTS.minMag,
    maxMag: Number.isFinite(maxMag) ? Math.max(0, Math.min(9, maxMag)) : DEFAULTS.maxMag,
    depthMin: Number.isFinite(depthMin) ? Math.max(0, Math.min(MAX_DEPTH, depthMin)) : DEFAULTS.depthMin,
    depthMax: Number.isFinite(depthMax) ? Math.max(0, Math.min(MAX_DEPTH, depthMax)) : DEFAULTS.depthMax,
    alert: ['all', 'green', 'yellow', 'orange', 'red', 'unknown'].includes(params.get('alert')) ? params.get('alert') : DEFAULTS.alert,
    tsunamiOnly: params.get('tsunami') === '1',
    reviewedOnly: params.get('reviewed') === '1',
    placeQuery: params.get('place') || DEFAULTS.placeQuery,
    sort: ['time', 'magnitude', 'depth'].includes(params.get('sort')) ? params.get('sort') : DEFAULTS.sort,
    selectedEventId: params.get('event') || '',
  };
}

function normalizeFeature(feature, index) {
  const properties = feature?.properties || {};
  const coordinates = feature?.geometry?.coordinates || [];
  const longitude = Number(coordinates[0]);
  const latitude = Number(coordinates[1]);
  const depth = Number(coordinates[2]);
  const time = Number(properties.time);
  if (!Number.isFinite(latitude) || !Number.isFinite(longitude) || !Number.isFinite(time)) return null;
  const magnitude = Number(properties.mag);
  const significance = Number(properties.sig);
  const felt = Number(properties.felt);
  return {
    id: String(properties.code || feature.id || `event-${time}-${index}`),
    magnitude: Number.isFinite(magnitude) ? magnitude : null,
    place: properties.place || 'Location not reported',
    title: properties.title || properties.place || 'Earthquake',
    time,
    updated: Number(properties.updated) || null,
    latitude,
    longitude,
    depth: Number.isFinite(depth) ? depth : null,
    felt: Number.isFinite(felt) ? felt : null,
    significance: Number.isFinite(significance) ? significance : null,
    alert: properties.alert || null,
    tsunami: properties.tsunami === 1 || properties.tsunami === '1',
    status: properties.status || null,
    eventType: properties.type || null,
    url: properties.url || null,
    detail: properties.detail || null,
    network: properties.net || null,
  };
}

function formatNumber(value) {
  return new Intl.NumberFormat('en-US').format(value);
}

function formatMagnitude(value) {
  return Number.isFinite(value) ? value.toFixed(1) : '—';
}

function formatDepth(value) {
  return Number.isFinite(value) ? `${value.toFixed(value < 10 ? 1 : 0)} km` : 'Depth not reported';
}

function formatRelativeTime(timestamp, now = Date.now()) {
  if (!Number.isFinite(timestamp)) return 'Time not reported';
  const seconds = Math.max(0, Math.round((now - timestamp) / 1000));
  if (seconds < 60) return 'just now';
  if (seconds < 3600) return `${Math.floor(seconds / 60)}m ago`;
  if (seconds < 86400) return `${Math.floor(seconds / 3600)}h ago`;
  return `${Math.floor(seconds / 86400)}d ago`;
}

function formatLocalTime(timestamp) {
  if (!Number.isFinite(timestamp)) return 'Time not reported';
  return new Intl.DateTimeFormat(undefined, {
    dateStyle: 'medium',
    timeStyle: 'short',
  }).format(new Date(timestamp));
}

function formatUtcTime(timestamp) {
  if (!Number.isFinite(timestamp)) return 'Time not reported';
  return new Intl.DateTimeFormat('en-GB', {
    dateStyle: 'medium',
    timeStyle: 'short',
    timeZone: 'UTC',
    timeZoneName: 'short',
  }).format(new Date(timestamp));
}

function formatAge(timestamp, now = Date.now()) {
  if (!timestamp) return 'Not refreshed yet';
  const seconds = Math.max(0, Math.floor((now - timestamp) / 1000));
  if (seconds < 60) return 'refreshed just now';
  if (seconds < 3600) return `refreshed ${Math.floor(seconds / 60)}m ago`;
  return `refreshed ${Math.floor(seconds / 3600)}h ago`;
}

function formatWindow(start, end) {
  if (!start || !end) return '';
  const sameDay = new Date(start).toDateString() === new Date(end).toDateString();
  const startText = new Intl.DateTimeFormat(undefined, { month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit' }).format(new Date(start));
  const endText = new Intl.DateTimeFormat(undefined, sameDay ? { hour: 'numeric', minute: '2-digit' } : { month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit' }).format(new Date(end));
  return `${startText} – ${endText}`;
}

function formatBucketLabel(timestamp, timeframe) {
  const options = timeframe === 'month'
    ? { month: 'short', day: 'numeric' }
    : timeframe === 'week'
      ? { weekday: 'short', hour: 'numeric' }
      : { hour: 'numeric', minute: '2-digit' };
  return new Intl.DateTimeFormat(undefined, options).format(new Date(timestamp));
}

function getAlertLabel(alert) {
  return alert ? `${alert[0].toUpperCase()}${alert.slice(1)} alert` : 'No alert level';
}

function getAlertClass(alert) {
  return alert ? `alert-${alert}` : 'alert-unknown';
}

function colorForMagnitude(magnitude) {
  if (!Number.isFinite(magnitude)) return '#71817e';
  if (magnitude < 2) return '#8ba6a0';
  if (magnitude < 4) return '#bb9860';
  if (magnitude < 5) return '#c46f4d';
  return '#ad4037';
}

function App() {
  const initialState = useMemo(() => readInitialState(), []);
  const [timeframe, setTimeframe] = useState(initialState.timeframe);
  const [minMag, setMinMag] = useState(initialState.minMag);
  const [maxMag, setMaxMag] = useState(Math.max(initialState.maxMag, initialState.minMag));
  const [depthMin, setDepthMin] = useState(Math.min(initialState.depthMin, initialState.depthMax));
  const [depthMax, setDepthMax] = useState(Math.max(initialState.depthMax, initialState.depthMin));
  const [alert, setAlert] = useState(initialState.alert);
  const [tsunamiOnly, setTsunamiOnly] = useState(initialState.tsunamiOnly);
  const [reviewedOnly, setReviewedOnly] = useState(initialState.reviewedOnly);
  const [placeQuery, setPlaceQuery] = useState(initialState.placeQuery);
  const [sort, setSort] = useState(initialState.sort);
  const [events, setEvents] = useState([]);
  const [loadState, setLoadState] = useState('loading');
  const [error, setError] = useState('');
  const [lastUpdated, setLastUpdated] = useState(null);
  const [nowTick, setNowTick] = useState(Date.now());
  const [selectedEventId, setSelectedEventId] = useState(initialState.selectedEventId);
  const [hoveredEventId, setHoveredEventId] = useState('');
  const [timelineWindow, setTimelineWindow] = useState(null);
  const [activeTooltip, setActiveTooltip] = useState(null);
  const [streamLimit, setStreamLimit] = useState(160);
  const [shareState, setShareState] = useState('');
  const [geocodeState, setGeocodeState] = useState({ status: 'idle', label: '' });
  const [mapZoom, setMapZoom] = useState(2);

  const mapContainerRef = useRef(null);
  const mapInstanceRef = useRef(null);
  const markerLayerRef = useRef(null);
  const abortControllerRef = useRef(null);
  const eventsRef = useRef(events);
  const detailRef = useRef(null);

  useEffect(() => {
    eventsRef.current = events;
  }, [events]);

  useEffect(() => {
    const interval = window.setInterval(() => setNowTick(Date.now()), 60 * 1000);
    return () => window.clearInterval(interval);
  }, []);

  const loadFeed = useCallback(async (range) => {
    if (abortControllerRef.current) abortControllerRef.current.abort();
    const controller = new AbortController();
    abortControllerRef.current = controller;
    setLoadState(eventsRef.current.length ? 'refreshing' : 'loading');
    setError('');
    try {
      const response = await fetch(`${USGS_FEED_ROOT}${FEEDS[range].path}?updated=${Date.now()}`, {
        signal: controller.signal,
        headers: { Accept: 'application/geo+json' },
      });
      if (!response.ok) throw new Error(`USGS returned ${response.status}`);
      const payload = await response.json();
      const nextEvents = (Array.isArray(payload.features) ? payload.features : [])
        .map(normalizeFeature)
        .filter(Boolean)
        .sort((a, b) => b.time - a.time);
      setEvents(nextEvents);
      setLastUpdated(Date.now());
      setLoadState('ready');
    } catch (requestError) {
      if (requestError?.name === 'AbortError') return;
      setError('The USGS feed could not be reached. The last displayed data is preserved.');
      setLoadState('error');
    }
  }, []);

  useEffect(() => {
    loadFeed(timeframe);
    const interval = window.setInterval(() => loadFeed(timeframe), 5 * 60 * 1000);
    return () => window.clearInterval(interval);
  }, [loadFeed, timeframe]);

  useEffect(() => () => abortControllerRef.current?.abort(), []);

  useEffect(() => {
    const params = new URLSearchParams();
    params.set('range', timeframe);
    if (minMag > DEFAULTS.minMag) params.set('minMag', String(minMag));
    if (maxMag < DEFAULTS.maxMag) params.set('maxMag', String(maxMag));
    if (depthMin > DEFAULTS.depthMin) params.set('depthMin', String(depthMin));
    if (depthMax < DEFAULTS.depthMax) params.set('depthMax', String(depthMax));
    if (alert !== DEFAULTS.alert) params.set('alert', alert);
    if (tsunamiOnly) params.set('tsunami', '1');
    if (reviewedOnly) params.set('reviewed', '1');
    if (placeQuery) params.set('place', placeQuery);
    if (sort !== DEFAULTS.sort) params.set('sort', sort);
    if (selectedEventId) params.set('event', selectedEventId);
    if (timelineWindow) {
      params.set('from', String(timelineWindow.start));
      params.set('to', String(timelineWindow.end));
    }
    const nextSearch = `?${params.toString()}`;
    if (window.location.search !== nextSearch) window.history.replaceState({}, '', `${window.location.pathname}${nextSearch}${window.location.hash}`);
  }, [timeframe, minMag, maxMag, depthMin, depthMax, alert, tsunamiOnly, reviewedOnly, placeQuery, sort, selectedEventId, timelineWindow]);

  const filteredEvents = useMemo(() => events.filter((event) => {
    const placeMatch = !placeQuery || event.place.toLowerCase().includes(placeQuery.trim().toLowerCase());
    const magMatch = (event.magnitude === null || (event.magnitude >= minMag && event.magnitude <= maxMag));
    const depthMatch = event.depth === null || (event.depth >= depthMin && event.depth <= depthMax);
    const alertMatch = alert === 'all' || (alert === 'unknown' ? !event.alert : event.alert === alert);
    const tsunamiMatch = !tsunamiOnly || event.tsunami;
    const reviewedMatch = !reviewedOnly || event.status === 'reviewed';
    return placeMatch && magMatch && depthMatch && alertMatch && tsunamiMatch && reviewedMatch;
  }), [events, placeQuery, minMag, maxMag, depthMin, depthMax, alert, tsunamiOnly, reviewedOnly]);

  const sortedEvents = useMemo(() => [...filteredEvents].sort((a, b) => {
    if (sort === 'magnitude') return (b.magnitude ?? -Infinity) - (a.magnitude ?? -Infinity) || b.time - a.time;
    if (sort === 'depth') return (a.depth ?? Infinity) - (b.depth ?? Infinity) || b.time - a.time;
    return b.time - a.time;
  }), [filteredEvents, sort]);

  const strongestEvent = useMemo(() => [...filteredEvents].sort((a, b) => (b.magnitude ?? -Infinity) - (a.magnitude ?? -Infinity) || b.time - a.time)[0] || null, [filteredEvents]);
  const selectedEvent = useMemo(() => filteredEvents.find((event) => event.id === selectedEventId) || strongestEvent, [filteredEvents, selectedEventId, strongestEvent]);

  useEffect(() => {
    if (!selectedEventId && strongestEvent) setSelectedEventId(strongestEvent.id);
  }, [selectedEventId, strongestEvent]);

  const timelineBuckets = useMemo(() => {
    const range = FEEDS[timeframe];
    const bucketCount = timeframe === 'hour' ? 12 : timeframe === 'day' ? 24 : timeframe === 'week' ? 28 : 30;
    const end = nowTick;
    const start = end - range.durationMs;
    const bucketDuration = range.durationMs / bucketCount;
    return Array.from({ length: bucketCount }, (_, index) => {
      const bucketStart = start + index * bucketDuration;
      const bucketEnd = bucketStart + bucketDuration;
      const bucketEvents = filteredEvents.filter((event) => event.time >= bucketStart && event.time < bucketEnd);
      return {
        index,
        start: bucketStart,
        end: bucketEnd,
        events: bucketEvents,
        count: bucketEvents.length,
        maxMagnitude: Math.max(...bucketEvents.map((event) => event.magnitude ?? 0), 0),
      };
    });
  }, [filteredEvents, nowTick, timeframe]);

  const selectedBucketIndex = useMemo(() => selectedEvent ? timelineBuckets.findIndex((bucket) => selectedEvent.time >= bucket.start && selectedEvent.time < bucket.end) : -1, [selectedEvent, timelineBuckets]);
  const timelineWindowEvents = timelineWindow ? filteredEvents.filter((event) => event.time >= timelineWindow.start && event.time < timelineWindow.end) : [];
  const maxTimelineCount = Math.max(...timelineBuckets.map((bucket) => bucket.count), 1);

  const depthBuckets = useMemo(() => {
    const bands = [
      { label: 'Shallow', sublabel: '0–20 km', min: 0, max: 20 },
      { label: 'Crustal', sublabel: '20–70 km', min: 20, max: 70 },
      { label: 'Intermediate', sublabel: '70–300 km', min: 70, max: 300 },
      { label: 'Deep', sublabel: '300+ km', min: 300, max: MAX_DEPTH },
    ];
    return bands.map((band) => ({
      ...band,
      count: filteredEvents.filter((event) => event.depth !== null && event.depth >= band.min && (band.max === MAX_DEPTH ? event.depth <= MAX_DEPTH : event.depth < band.max)).length,
    }));
  }, [filteredEvents]);
  const maxDepthCount = Math.max(...depthBuckets.map((band) => band.count), 1);

  const selectEvent = useCallback((event, shouldScroll = true) => {
    setSelectedEventId(event.id);
    if (shouldScroll && window.innerWidth < 980) {
      window.requestAnimationFrame(() => detailRef.current?.scrollIntoView({ behavior: window.matchMedia('(prefers-reduced-motion: reduce)').matches ? 'auto' : 'smooth', block: 'start' }));
    }
  }, []);

  const focusEventOnMap = useCallback((event) => {
    selectEvent(event, false);
    mapInstanceRef.current?.panTo([event.latitude, event.longitude], { animate: !window.matchMedia('(prefers-reduced-motion: reduce)').matches });
  }, [selectEvent]);

  const resetFilters = useCallback(() => {
    setMinMag(DEFAULTS.minMag);
    setMaxMag(DEFAULTS.maxMag);
    setDepthMin(DEFAULTS.depthMin);
    setDepthMax(DEFAULTS.depthMax);
    setAlert(DEFAULTS.alert);
    setTsunamiOnly(DEFAULTS.tsunamiOnly);
    setReviewedOnly(DEFAULTS.reviewedOnly);
    setPlaceQuery(DEFAULTS.placeQuery);
    setSort(DEFAULTS.sort);
    setTimelineWindow(null);
    setSelectedEventId('');
    setStreamLimit(160);
  }, []);

  const copyShareLink = useCallback(async () => {
    const url = window.location.href;
    try {
      if (!navigator.clipboard) throw new Error('Clipboard unavailable');
      await navigator.clipboard.writeText(url);
      setShareState('Link copied');
    } catch {
      window.prompt('Copy this observatory link', url);
      setShareState('Link ready to copy');
    }
    window.setTimeout(() => setShareState(''), 2500);
  }, []);

  const geocodePlace = useCallback(async (event) => {
    event?.preventDefault();
    const query = placeQuery.trim();
    if (!query) {
      setGeocodeState({ status: 'idle', label: '' });
      return;
    }
    setGeocodeState({ status: 'loading', label: '' });
    try {
      const response = await fetch(`https://nominatim.openstreetmap.org/search?format=jsonv2&limit=1&q=${encodeURIComponent(query)}`, {
        headers: { Accept: 'application/json' },
      });
      if (!response.ok) throw new Error('Geocoder unavailable');
      const results = await response.json();
      const result = results?.[0];
      if (!result) throw new Error('Place not found');
      const latitude = Number(result.lat);
      const longitude = Number(result.lon);
      mapInstanceRef.current?.setView([latitude, longitude], Math.max(mapInstanceRef.current.getZoom(), 5), { animate: !window.matchMedia('(prefers-reduced-motion: reduce)').matches });
      setGeocodeState({ status: 'ready', label: result.display_name });
    } catch {
      setGeocodeState({ status: 'error', label: 'Place not found. Try a country, city, or region.' });
    }
  }, [placeQuery]);

  useEffect(() => {
    if (mapInstanceRef.current || !mapContainerRef.current) return undefined;
    const map = L.map(mapContainerRef.current, {
      center: [18, 0],
      zoom: 2,
      minZoom: 2,
      maxZoom: 9,
      worldCopyJump: true,
      zoomControl: false,
      attributionControl: true,
    });
    L.tileLayer('https://{s}.basemaps.cartocdn.com/light_all/{z}/{x}/{y}{r}.png', {
      maxZoom: 20,
      attribution: '&copy; OpenStreetMap contributors &copy; CARTO',
      subdomains: 'abcd',
    }).addTo(map);
    L.control.zoom({ position: 'bottomright' }).addTo(map);
    markerLayerRef.current = L.layerGroup().addTo(map);
    mapInstanceRef.current = map;
    setMapZoom(map.getZoom());
    const handleResize = () => map.invalidateSize();
    const handleZoom = () => setMapZoom(map.getZoom());
    window.addEventListener('resize', handleResize);
    map.on('zoomend', handleZoom);
    window.setTimeout(() => map.invalidateSize(), 0);
    return () => {
      window.removeEventListener('resize', handleResize);
      map.remove();
      mapInstanceRef.current = null;
      markerLayerRef.current = null;
    };
  }, []);

  useEffect(() => {
    const map = mapInstanceRef.current;
    const layer = markerLayerRef.current;
    if (!map || !layer) return;
    layer.clearLayers();
    const clusterSize = mapZoom <= 2 ? 18 : mapZoom <= 3 ? 8 : mapZoom <= 4 ? 4 : mapZoom <= 5 ? 1.5 : 0;
    const groups = new Map();
    filteredEvents.forEach((event) => {
      const key = clusterSize ? `${Math.floor((event.latitude + 90) / clusterSize)}:${Math.floor((event.longitude + 180) / clusterSize)}` : event.id;
      if (!groups.has(key)) groups.set(key, []);
      groups.get(key).push(event);
    });

    groups.forEach((group) => {
      if (group.length > 1) {
        const latitude = group.reduce((sum, event) => sum + event.latitude, 0) / group.length;
        const longitude = group.reduce((sum, event) => sum + event.longitude, 0) / group.length;
        const maxMagnitude = Math.max(...group.map((event) => event.magnitude ?? 0));
        const inTimeline = !timelineWindow || group.some((event) => event.time >= timelineWindow.start && event.time < timelineWindow.end);
        const icon = L.divIcon({
          className: 'quake-cluster-icon',
          html: `<span class="quake-cluster ${maxMagnitude >= 5 ? 'quake-cluster-large' : ''} ${inTimeline ? '' : 'quake-marker-muted'}"><b>${group.length}</b><small>M${formatMagnitude(maxMagnitude)}</small></span>`,
          iconSize: [56, 56],
          iconAnchor: [28, 28],
        });
        const marker = L.marker([latitude, longitude], { icon, keyboard: true, title: `${group.length} earthquakes in this area` });
        marker.bindTooltip(`${group.length} events · strongest M${formatMagnitude(maxMagnitude)}`, { direction: 'top', offset: [0, -26] });
        const bounds = L.latLngBounds(group.map((event) => [event.latitude, event.longitude]));
        marker.on('click', () => {
          if (bounds.isValid() && bounds.getNorthEast().equals(bounds.getSouthWest())) map.setView([latitude, longitude], Math.min(map.getZoom() + 2, 9));
          else map.fitBounds(bounds.pad(0.18), { maxZoom: Math.min(map.getZoom() + 3, 8) });
        });
        layer.addLayer(marker);
        return;
      }
      const event = group[0];
      const inTimeline = !timelineWindow || (event.time >= timelineWindow.start && event.time < timelineWindow.end);
      const isFocused = event.id === selectedEvent?.id || event.id === hoveredEventId;
      const alertStroke = event.alert === 'red' ? '#9d3030' : event.alert === 'orange' ? '#b56335' : event.alert === 'yellow' ? '#a77b31' : '#203538';
      const marker = L.circleMarker([event.latitude, event.longitude], {
        radius: Math.max(4, 4 + (event.magnitude ?? 0) * 1.4),
        fillColor: colorForMagnitude(event.magnitude),
        color: isFocused ? '#17252a' : alertStroke,
        weight: isFocused ? 3 : event.tsunami ? 3 : 1.5,
        opacity: inTimeline ? 1 : 0.2,
        fillOpacity: inTimeline ? (isFocused ? 0.98 : 0.78) : 0.12,
        dashArray: event.tsunami ? '4 3' : undefined,
      });
      marker.bindTooltip(`M${formatMagnitude(event.magnitude)} · ${event.place} · ${formatDepth(event.depth)}`, { direction: 'top', offset: [0, -8] });
      marker.on('click', () => selectEvent(event, false));
      marker.on('mouseover', () => setHoveredEventId(event.id));
      marker.on('mouseout', () => setHoveredEventId(''));
      marker.on('focus', () => setHoveredEventId(event.id));
      marker.on('blur', () => setHoveredEventId(''));
      if (isFocused) marker.bringToFront();
      layer.addLayer(marker);
    });
  }, [filteredEvents, hoveredEventId, mapZoom, selectEvent, selectedEvent?.id, timelineWindow]);

  const filterChips = [
    minMag > 0 ? { label: `M ≥ ${minMag.toFixed(1)}`, clear: () => setMinMag(0) } : null,
    maxMag < 9 ? { label: `M ≤ ${maxMag.toFixed(1)}`, clear: () => setMaxMag(9) } : null,
    depthMin > 0 || depthMax < MAX_DEPTH ? { label: `${depthMin}–${depthMax === MAX_DEPTH ? '700+' : depthMax} km`, clear: () => { setDepthMin(0); setDepthMax(MAX_DEPTH); } } : null,
    alert !== 'all' ? { label: getAlertLabel(alert), clear: () => setAlert('all') } : null,
    tsunamiOnly ? { label: 'Tsunami flag', clear: () => setTsunamiOnly(false) } : null,
    reviewedOnly ? { label: 'Reviewed origins', clear: () => setReviewedOnly(false) } : null,
    placeQuery ? { label: `Place: ${placeQuery}`, clear: () => { setPlaceQuery(''); setGeocodeState({ status: 'idle', label: '' }); } } : null,
  ].filter(Boolean);

  const eventIsInWindow = (event) => !timelineWindow || (event.time >= timelineWindow.start && event.time < timelineWindow.end);
  const visibleStreamEvents = sortedEvents.slice(0, streamLimit);
  const dataAge = formatAge(lastUpdated, nowTick);
  const isLoading = loadState === 'loading';
  const isRefreshing = loadState === 'refreshing';
  const isStale = Boolean(lastUpdated && nowTick - lastUpdated > 15 * 60 * 1000);

  return (
    <div className="app-shell">
      <header className="topbar">
        <a className="brand-lockup" href="#top" aria-label="Seismic Observatory home">
          <span className="brand-mark" aria-hidden="true"><i /><i /><i /></span>
          <span>
            <span className="brand-name">Seismic Observatory</span>
            <span className="brand-caption">A live field guide to a moving planet</span>
          </span>
        </a>
        <nav className="topnav" aria-label="Primary navigation">
          <a href="#activity">Activity</a>
          <a href="#stream">Event stream</a>
          <a href="#method">Method</a>
        </nav>
        <div className="top-actions">
          <span className={`connection-status ${isStale || loadState === 'error' ? 'status-stale' : ''}`}>
            <span className="status-dot" aria-hidden="true" />
            {loadState === 'error' ? 'Stale feed' : isRefreshing ? 'Updating' : 'Live feed'}
          </span>
          <button className="button button-dark button-small" type="button" onClick={() => loadFeed(timeframe)} disabled={isLoading || isRefreshing}>
            <span aria-hidden="true">↻</span> Refresh
          </button>
        </div>
      </header>

      <main id="top">
        <section className="intro-band" aria-labelledby="page-title">
          <div>
            <p className="eyebrow">Global seismic field · {FEEDS[timeframe].label}</p>
            <h1 id="page-title">Read the planet in motion.</h1>
            <p className="intro-copy">A calm, live view of where earthquakes are happening, how deep they are, and which signals deserve a closer look.</p>
          </div>
          <div className="intro-note">
            <span className="eyebrow">Data position</span>
            <strong>{dataAge}</strong>
            <span>USGS real-time GeoJSON · times shown in your local zone and UTC</span>
          </div>
        </section>

        <section className="signal-summary" aria-label="Current earthquake summary">
          <div className="summary-count">
            <span className="summary-label">Observed in window</span>
            <strong>{isLoading && events.length === 0 ? '—' : formatNumber(filteredEvents.length)}</strong>
            <span className="summary-subline">{filteredEvents.length === 1 ? 'earthquake matches' : 'earthquakes match'} current view</span>
          </div>
          <div className="summary-divider" aria-hidden="true" />
          <div className="summary-story">
            <span className="summary-label">Strongest signal in view</span>
            {strongestEvent ? (
              <button className="strongest-link" type="button" onClick={() => selectEvent(strongestEvent)}>
                <span className="magnitude-stamp">M{formatMagnitude(strongestEvent.magnitude)}</span>
                <span><b>{strongestEvent.place}</b><small>{formatRelativeTime(strongestEvent.time, nowTick)} · {formatDepth(strongestEvent.depth)}</small></span>
                <span className="arrow-mark" aria-hidden="true">↗</span>
              </button>
            ) : <span className="summary-empty">No event matches the current constraints.</span>}
          </div>
          <div className="summary-legend">
            <span className="summary-label">Reading the map</span>
            <span><i className="legend-dot legend-small" /> radius = magnitude</span>
            <span><i className="legend-ring" /> ring = alert / tsunami flag</span>
          </div>
        </section>

        <section className="control-deck" aria-label="Explore and filter earthquake data">
          <div className="time-rail">
            <span className="control-label">Time window</span>
            <div className="segmented-control" role="group" aria-label="Choose a time window">
              {Object.entries(FEEDS).map(([key, range]) => (
                <button key={key} type="button" className={timeframe === key ? 'is-active' : ''} aria-pressed={timeframe === key} onClick={() => { setTimeframe(key); setTimelineWindow(null); setStreamLimit(160); }}>
                  <span>{range.label}</span><small>{range.shortLabel}</small>
                </button>
              ))}
            </div>
          </div>
          <div className="control-actions">
            <button className="button button-light" type="button" onClick={copyShareLink}><span aria-hidden="true">⌁</span> Share view</button>
            <button className="button button-quiet" type="button" onClick={resetFilters} disabled={!filterChips.length && !timelineWindow}>Reset all</button>
            {shareState && <span className="action-feedback" role="status">{shareState}</span>}
          </div>

          <div className="filter-grid">
            <fieldset className="filter-group magnitude-filter">
              <legend>Magnitude</legend>
              <div className="range-pair">
                <label><span>At least</span><output>M{minMag.toFixed(1)}</output><input type="range" min="0" max="9" step="0.1" value={minMag} onChange={(event) => setMinMag(Math.min(Number(event.target.value), maxMag))} /></label>
                <label><span>At most</span><output>{maxMag >= 9 ? 'Any' : `M${maxMag.toFixed(1)}`}</output><input type="range" min="0" max="9" step="0.1" value={maxMag} onChange={(event) => setMaxMag(Math.max(Number(event.target.value), minMag))} /></label>
              </div>
            </fieldset>
            <fieldset className="filter-group depth-filter">
              <legend>Depth, kilometers</legend>
              <div className="number-pair">
                <label><span>From</span><input type="number" min="0" max={MAX_DEPTH} value={depthMin} onChange={(event) => setDepthMin(Math.min(MAX_DEPTH, Math.max(0, Number(event.target.value) || 0)))} /></label>
                <span className="number-dash" aria-hidden="true">—</span>
                <label><span>To</span><input type="number" min="0" max={MAX_DEPTH} value={depthMax === MAX_DEPTH ? '' : depthMax} placeholder="700+" onChange={(event) => setDepthMax(Math.min(MAX_DEPTH, Math.max(depthMin, Number(event.target.value) || MAX_DEPTH)))} /></label>
              </div>
            </fieldset>
            <label className="select-control"><span>Alert level</span><select value={alert} onChange={(event) => setAlert(event.target.value)}><option value="all">Any alert level</option><option value="green">Green</option><option value="yellow">Yellow</option><option value="orange">Orange</option><option value="red">Red</option><option value="unknown">Not reported</option></select></label>
            <label className="select-control"><span>Sort stream by</span><select value={sort} onChange={(event) => setSort(event.target.value)}><option value="time">Newest first</option><option value="magnitude">Largest first</option><option value="depth">Shallowest first</option></select></label>
            <form className="place-search" onSubmit={geocodePlace}>
              <label htmlFor="place-query">Place or region</label>
              <div className="search-row"><input id="place-query" type="search" value={placeQuery} onChange={(event) => setPlaceQuery(event.target.value)} placeholder="Filter or find a place" /><button type="submit" className="search-button" aria-label="Find place on map">⌕</button></div>
              {geocodeState.status === 'loading' && <small className="field-status">Looking up place…</small>}
              {geocodeState.status === 'ready' && <small className="field-status field-status-good">Map centered on {geocodeState.label}</small>}
              {geocodeState.status === 'error' && <small className="field-status field-status-error">{geocodeState.label}</small>}
            </form>
            <div className="check-control">
              <span className="control-subhead">Signals</span>
              <label><input type="checkbox" checked={tsunamiOnly} onChange={(event) => setTsunamiOnly(event.target.checked)} /> <span>Tsunami flag</span></label>
              <label><input type="checkbox" checked={reviewedOnly} onChange={(event) => setReviewedOnly(event.target.checked)} /> <span>Reviewed origins</span></label>
            </div>
          </div>
          <div className="active-filters" aria-live="polite">
            <span className="active-label">{formatNumber(filteredEvents.length)} of {formatNumber(events.length)} events</span>
            {filterChips.length ? filterChips.map((chip) => <button key={chip.label} type="button" className="filter-chip" onClick={chip.clear}>{chip.label}<span aria-hidden="true">×</span></button>) : <span className="no-filters">All available events shown</span>}
            {timelineWindow && <button className="filter-chip filter-chip-time" type="button" onClick={() => setTimelineWindow(null)}>Timeline · {formatWindow(timelineWindow.start, timelineWindow.end)} ×</button>}
          </div>
        </section>

        <div className="workspace" id="activity">
          <div className="map-column">
            <section className="map-panel" aria-labelledby="map-heading">
              <div className="panel-heading map-heading">
                <div><p className="eyebrow">Geographic field</p><h2 id="map-heading">Where the ground is moving</h2></div>
                <div className="map-heading-actions"><span className="map-zoom">Zoom {mapZoom.toFixed(1)}</span><button type="button" className="icon-button" onClick={() => mapInstanceRef.current?.setView([18, 0], 2)} aria-label="Reset map to world view">◎</button></div>
              </div>
              <div className="map-frame">
                <div ref={mapContainerRef} className="map-container" tabIndex="0" aria-label="Interactive world map of earthquakes. Use the event stream below as a keyboard-accessible alternative." />
                <div className="map-key" aria-label="Map legend">
                  <span><i className="key-swatch key-low" /> smaller magnitude</span>
                  <span><i className="key-swatch key-high" /> larger magnitude</span>
                  <span><i className="key-outline" /> tsunami flag</span>
                </div>
                {(isLoading || isRefreshing) && <div className="map-loading" role="status" aria-live="polite"><span className="loader-line" />{isLoading ? 'Loading live USGS events…' : 'Refreshing without losing your place…'}</div>}
                {error && <div className="map-error" role="alert"><strong>Live update paused</strong><span>{error}</span><button type="button" className="button button-light button-small" onClick={() => loadFeed(timeframe)}>Try again</button></div>}
                {!isLoading && !error && !filteredEvents.length && <div className="map-empty"><span className="empty-glyph" aria-hidden="true">⌁</span><strong>No events match</strong><span>Loosen a filter or reset the view to return to the field.</span><button type="button" className="button button-dark button-small" onClick={resetFilters}>Reset filters</button></div>}
              </div>
              <div className="map-caption"><span>{timelineWindow ? `${formatNumber(timelineWindowEvents.length)} events illuminated in selected time slice` : 'Select a marker, cluster, or event row to follow one signal through every view.'}</span><span className="map-attribution">Basemap © CARTO · Events © USGS</span></div>
            </section>

            <section className="timeline-panel" aria-labelledby="timeline-heading">
              <div className="panel-heading timeline-heading">
                <div><p className="eyebrow">Signature interaction · connected time</p><h2 id="timeline-heading">When the field changed</h2></div>
                <div className="timeline-meta"><span>{timelineWindow ? `${formatNumber(timelineWindowEvents.length)} in slice` : 'Click a band to illuminate its events'}</span>{timelineWindow && <button type="button" className="text-button" onClick={() => setTimelineWindow(null)}>Clear slice</button>}</div>
              </div>
              <div className="timeline-chart-wrap">
                <svg className="timeline-chart" viewBox="0 0 1000 190" role="img" aria-labelledby="timeline-heading timeline-description">
                  <desc id="timeline-description">Activity volume by time bucket. Bar height shows the number of matching earthquakes; the warm cap marks the strongest magnitude in each bucket.</desc>
                  <line x1="42" x2="974" y1="148" y2="148" className="chart-baseline" />
                  <line x1="42" x2="974" y1="96" y2="96" className="chart-gridline" />
                  <line x1="42" x2="974" y1="44" y2="44" className="chart-gridline" />
                  <text x="12" y="151" className="chart-axis-label">0</text>
                  <text x="6" y="99" className="chart-axis-label">{Math.ceil(maxTimelineCount / 2)}</text>
                  <text x="4" y="47" className="chart-axis-label">{maxTimelineCount}</text>
                  {timelineBuckets.map((bucket) => {
                    const x = 46 + bucket.index * (928 / timelineBuckets.length);
                    const barWidth = Math.max(5, 928 / timelineBuckets.length - 4);
                    const height = (bucket.count / maxTimelineCount) * 104;
                    const y = 148 - height;
                    const isSelected = timelineWindow && bucket.start === timelineWindow.start;
                    const isFocused = bucket.index === selectedBucketIndex;
                    return <g key={bucket.start} className="timeline-bar-group">
                      <rect x={x} y="22" width={barWidth} height="126" className={`timeline-hit-area ${isSelected ? 'timeline-hit-selected' : ''}`} tabIndex="0" role="button" aria-label={`${formatBucketLabel(bucket.start, timeframe)}: ${bucket.count} earthquakes, strongest magnitude ${formatMagnitude(bucket.maxMagnitude)}`} onClick={() => setTimelineWindow({ start: bucket.start, end: bucket.end })} onKeyDown={(event) => { if (event.key === 'Enter' || event.key === ' ') { event.preventDefault(); setTimelineWindow({ start: bucket.start, end: bucket.end }); } }} onMouseEnter={() => setActiveTooltip({ index: bucket.index, x: x + barWidth / 2 })} onMouseLeave={() => setActiveTooltip(null)} onFocus={() => setActiveTooltip({ index: bucket.index, x: x + barWidth / 2 })} onBlur={() => setActiveTooltip(null)} />
                      <rect x={x} y={y} width={barWidth} height={Math.max(height, bucket.count ? 3 : 0)} rx="3" className={`timeline-bar ${isSelected ? 'timeline-bar-selected' : ''} ${bucket.count ? '' : 'timeline-bar-empty'}`} />
                      {bucket.count > 0 && <rect x={x} y={Math.max(y, 22)} width={barWidth} height="4" rx="2" className="timeline-cap" />}
                      {isFocused && <line x1={x + barWidth / 2} x2={x + barWidth / 2} y1="16" y2="155" className="timeline-focus-line" />}
                      {(bucket.index === 0 || bucket.index === timelineBuckets.length - 1 || bucket.index === Math.floor(timelineBuckets.length / 2)) && <text x={x + barWidth / 2} y="176" textAnchor="middle" className="chart-x-label">{formatBucketLabel(bucket.start, timeframe)}</text>}
                    </g>;
                  })}
                </svg>
                {activeTooltip && timelineBuckets[activeTooltip.index] && <div className="timeline-tooltip" style={{ left: `${(activeTooltip.x / 1000) * 100}%` }} role="status"><b>{formatBucketLabel(timelineBuckets[activeTooltip.index].start, timeframe)}</b><span>{formatNumber(timelineBuckets[activeTooltip.index].count)} earthquakes · strongest M{formatMagnitude(timelineBuckets[activeTooltip.index].maxMagnitude)}</span></div>}
              </div>
              <div className="timeline-reading"><span className="timeline-reading-key"><i className="timeline-key-volume" /> activity volume</span><span className="timeline-reading-key"><i className="timeline-key-peak" /> highest magnitude in bucket</span><span className="timeline-reading-note">The focused line follows the selected event.</span></div>
            </section>

            <section className="depth-panel" aria-labelledby="depth-heading">
              <div className="panel-heading"><div><p className="eyebrow">Depth distribution</p><h2 id="depth-heading">How far below the surface</h2></div><span className="panel-note">Click a band to filter</span></div>
              <div className="depth-distribution" role="list" aria-label="Earthquake counts by depth band">
                {depthBuckets.map((band) => <button key={band.label} type="button" role="listitem" className={`depth-band ${depthMin === band.min && (band.max === MAX_DEPTH ? depthMax === MAX_DEPTH : depthMax === band.max) ? 'is-active' : ''}`} onClick={() => { setDepthMin(band.min); setDepthMax(band.max); }} aria-label={`${band.label}, ${band.sublabel}, ${band.count} events`}><span className="depth-band-copy"><b>{band.label}</b><small>{band.sublabel}</small></span><span className="depth-track"><i style={{ width: `${Math.max(2, (band.count / maxDepthCount) * 100)}%` }} /></span><strong>{formatNumber(band.count)}</strong></button>)}
              </div>
            </section>

            <section className="stream-panel" id="stream" aria-labelledby="stream-heading">
              <div className="panel-heading stream-heading"><div><p className="eyebrow">Accessible event stream</p><h2 id="stream-heading">Every signal, in order</h2></div><div className="stream-total"><strong>{formatNumber(sortedEvents.length)}</strong><span>matching events</span></div></div>
              {timelineWindow && <div className="stream-context" role="status">Time slice active · matching rows are marked with a warm edge; other rows remain in context.</div>}
              {!visibleStreamEvents.length && !isLoading ? <div className="stream-empty"><strong>No event rows to show.</strong><span>Reset filters to restore the live stream.</span><button type="button" className="button button-light button-small" onClick={resetFilters}>Reset filters</button></div> : <div className="event-list" role="list" aria-label="Earthquake event stream">{visibleStreamEvents.map((event) => {
                const selected = selectedEvent?.id === event.id;
                const inWindow = eventIsInWindow(event);
                return <button key={event.id} type="button" role="listitem" className={`event-row ${selected ? 'is-selected' : ''} ${inWindow ? 'is-in-window' : 'is-out-window'}`} aria-current={selected ? 'true' : undefined} onClick={() => selectEvent(event)} onMouseEnter={() => setHoveredEventId(event.id)} onMouseLeave={() => setHoveredEventId('')} onFocus={() => setHoveredEventId(event.id)} onBlur={() => setHoveredEventId('')}>
                  <span className="event-magnitude">M{formatMagnitude(event.magnitude)}</span>
                  <span className="event-row-main"><strong>{event.place}</strong><span>{formatRelativeTime(event.time, nowTick)} · {formatDepth(event.depth)}</span></span>
                  <span className="event-row-tags">{event.tsunami && <em className="tag tag-tsunami">Tsunami flag</em>}{event.alert && <em className={`tag ${getAlertClass(event.alert)}`}>{event.alert} alert</em>}{event.status === 'reviewed' && <em className="tag tag-reviewed">Reviewed</em>}</span>
                  <span className="event-row-arrow" aria-hidden="true">{selected ? '●' : '→'}</span>
                </button>;
              })}</div>}
              {visibleStreamEvents.length < sortedEvents.length && <button type="button" className="load-more" onClick={() => setStreamLimit((limit) => limit + 160)}>Load 160 more <span>({formatNumber(sortedEvents.length - visibleStreamEvents.length)} remaining)</span></button>}
              <p className="stream-footnote">Map-only insights are repeated here so the complete exploration path works by keyboard and touch.</p>
            </section>
          </div>

          <aside className="inspector" ref={detailRef} aria-labelledby="inspector-heading">
            <div className="inspector-topline"><span className="eyebrow">Focused event dossier</span><span className="dossier-index">{selectedEvent ? '01' : '—'}</span></div>
            {selectedEvent ? <>
              <div className="inspector-title-row"><div><span className="magnitude-hero">M{formatMagnitude(selectedEvent.magnitude)}</span><h2 id="inspector-heading">{selectedEvent.place}</h2></div><span className={`status-seal ${getAlertClass(selectedEvent.alert)}`}><i aria-hidden="true" />{selectedEvent.alert ? selectedEvent.alert : 'No alert'}</span></div>
              <p className="detail-lede">{selectedEvent.title}</p>
              <div className="detail-actions"><button type="button" className="button button-dark" onClick={() => focusEventOnMap(selectedEvent)}>Focus on map <span aria-hidden="true">↗</span></button>{selectedEvent.url && <a className="button button-light" href={selectedEvent.url} target="_blank" rel="noreferrer">Official USGS page <span aria-hidden="true">↗</span></a>}</div>
              <dl className="detail-grid">
                <div><dt>Local time</dt><dd>{formatLocalTime(selectedEvent.time)}</dd><small>Your device time zone</small></div>
                <div><dt>UTC time</dt><dd>{formatUtcTime(selectedEvent.time)}</dd><small>USGS reference clock</small></div>
                <div><dt>Depth</dt><dd>{formatDepth(selectedEvent.depth)}</dd><small>Below surface</small></div>
                <div><dt>Felt reports</dt><dd>{selectedEvent.felt === null ? 'Not reported' : formatNumber(selectedEvent.felt)}</dd><small>Public reports</small></div>
                <div><dt>Significance</dt><dd>{selectedEvent.significance === null ? 'Not reported' : formatNumber(selectedEvent.significance)}</dd><small>USGS index, not a damage score</small></div>
                <div><dt>Review status</dt><dd>{selectedEvent.status ? `${selectedEvent.status[0].toUpperCase()}${selectedEvent.status.slice(1)}` : 'Not reported'}</dd><small>Origin quality state</small></div>
                <div><dt>Tsunami flag</dt><dd>{selectedEvent.tsunami ? 'Yes' : 'No'}</dd><small>Check official page for updates</small></div>
                <div><dt>Coordinates</dt><dd>{selectedEvent.latitude.toFixed(3)}°, {selectedEvent.longitude.toFixed(3)}°</dd><small>{selectedEvent.network ? `Network ${selectedEvent.network}` : 'USGS network'}</small></div>
              </dl>
              <div className="detail-note"><span className="note-symbol" aria-hidden="true">i</span><p><strong>Read magnitude with context.</strong> Magnitude describes the energy released at the source. It does not predict damage, which depends on depth, distance, ground conditions, and many other factors.</p></div>
              <div className="detail-timestamp"><span>Event updated {selectedEvent.updated ? formatUtcTime(selectedEvent.updated) : 'time not reported'}</span><span>Data source: USGS</span></div>
            </> : <div className="inspector-empty"><span className="empty-glyph" aria-hidden="true">⌁</span><h2 id="inspector-heading">Waiting for the field</h2><p>The event dossier will appear when live USGS data arrives.</p></div>}
          </aside>
        </div>
      </main>

      <footer className="footer" id="method">
        <div><span className="brand-name">Seismic Observatory</span><p>Exploration, not emergency alerting. Earthquake data can be revised as seismic networks review new information.</p></div>
        <div className="footer-method"><span className="eyebrow">Method note</span><p>Events are loaded directly from the free USGS real-time GeoJSON feeds. Basemap © CARTO / OpenStreetMap. For authoritative updates, follow the official USGS event page and local authorities.</p></div>
        <span className="footer-mark" aria-hidden="true">⌁</span>
      </footer>
      <div className="sr-only" role="status" aria-live="polite">{isLoading ? 'Loading earthquake data.' : isRefreshing ? 'Refreshing earthquake data.' : `${formatNumber(filteredEvents.length)} earthquake results shown.`}</div>
    </div>
  );
}

export default App;

input.content:
@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Manrope:wght@400;500;600;700;800&family=Newsreader:opsz,wght@6..72,500;6..72,600&display=swap');

:root {
  --ink: #17252a;
  --ink-soft: #314044;
  --muted: #687370;
  --muted-light: #89928c;
  --paper: #f4f1e9;
  --paper-deep: #e9e5db;
  --surface: #fbf9f3;
  --surface-warm: #f0ede4;
  --line: #d3d0c6;
  --line-strong: #aeb5ad;
  --dark: #1a2b2e;
  --dark-soft: #284247;
  --signal: #c95743;
  --signal-bright: #dd7454;
  --amber: #b7924f;
  --teal: #6c918b;
  --good: #5d8678;
  --warning: #bd8b34;
  --serious: #bb643d;
  --critical: #9d3030;
  --shadow: 0 20px 55px rgba(29, 43, 43, 0.09);
  --shadow-soft: 0 8px 24px rgba(29, 43, 43, 0.07);
  --display: 'Newsreader', 'Iowan Old Style', 'Palatino Linotype', Georgia, serif;
  --body: 'Manrope', 'Avenir Next', Avenir, Helvetica, Arial, sans-serif;
  --mono: 'DM Mono', 'SFMono-Regular', Consolas, monospace;
}

* { box-sizing: border-box; }

html { scroll-behavior: smooth; }

body {
  margin: 0;
  min-width: 320px;
  background: var(--paper-deep);
  color: var(--ink);
  font-family: var(--body);
  font-size: 14px;
  line-height: 1.45;
  -webkit-font-smoothing: antialiased;
}

button, input, select { font: inherit; }
button, a { -webkit-tap-highlight-color: transparent; }
button { cursor: pointer; }
button:disabled { cursor: not-allowed; opacity: 0.5; }
a { color: inherit; }

:focus-visible {
  outline: 3px solid var(--signal-bright);
  outline-offset: 3px;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.app-shell {
  min-height: 100vh;
  background: var(--paper);
  overflow: clip;
}

.topbar {
  min-height: 76px;
  padding: 16px clamp(20px, 4vw, 64px);
  display: flex;
  align-items: center;
  gap: 32px;
  background: var(--dark);
  color: #f7f4eb;
  border-bottom: 1px solid rgba(255, 255, 255, 0.12);
}

.brand-lockup {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  text-decoration: none;
  min-width: max-content;
}

.brand-mark {
  width: 28px;
  height: 34px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 3px;
  border-left: 1px solid rgba(255, 255, 255, 0.35);
  border-right: 1px solid rgba(255, 255, 255, 0.35);
  transform: skewX(-9deg);
}

.brand-mark i {
  display: block;
  width: 2px;
  background: var(--signal-bright);
  border-radius: 4px;
  transform: skewX(9deg);
}

.brand-mark i:nth-child(1) { height: 12px; }
.brand-mark i:nth-child(2) { height: 25px; background: #e4b66f; }
.brand-mark i:nth-child(3) { height: 17px; }

.brand-name, .brand-caption { display: block; }
.brand-name { font-size: 12px; font-weight: 800; letter-spacing: 0.08em; text-transform: uppercase; }
.brand-caption { margin-top: 2px; color: #aebbb7; font-size: 10px; letter-spacing: 0.02em; }

.topnav { display: flex; align-items: center; gap: 24px; margin-left: auto; }
.topnav a { color: #c8d1cb; font-size: 12px; text-decoration: none; }
.topnav a:hover { color: #fff; }

.top-actions { display: flex; align-items: center; gap: 13px; }
.connection-status { display: inline-flex; align-items: center; gap: 7px; color: #a6d3b9; font-size: 11px; font-weight: 700; letter-spacing: 0.03em; white-space: nowrap; }
.connection-status.status-stale { color: #e5b481; }
.status-dot { width: 7px; height: 7px; display: inline-block; border-radius: 50%; background: #7bc492; box-shadow: 0 0 0 3px rgba(123, 196, 146, 0.13); }
.status-stale .status-dot { background: #e5a25f; box-shadow: 0 0 0 3px rgba(229, 162, 95, 0.14); }

.button, .icon-button, .text-button, .load-more, .filter-chip, .segmented-control button, .event-row, .depth-band, .strongest-link, .search-button { border: 0; }
.button { min-height: 44px; padding: 10px 15px; display: inline-flex; align-items: center; justify-content: center; gap: 8px; border-radius: 4px; font-size: 12px; font-weight: 800; letter-spacing: 0.01em; text-decoration: none; transition: background-color 160ms ease, color 160ms ease, border-color 160ms ease, transform 160ms ease; }
.button:hover:not(:disabled) { transform: translateY(-1px); }
.button-dark { background: var(--dark); color: #fff; }
.button-dark:hover:not(:disabled) { background: #29484d; }
.topbar .button-dark { background: #f4f1e9; color: var(--dark); }
.topbar .button-dark:hover:not(:disabled) { background: #fff; }
.button-light { background: var(--surface); color: var(--ink); border: 1px solid var(--line); }
.button-light:hover:not(:disabled) { background: #fff; border-color: var(--line-strong); }
.button-quiet { background: transparent; color: var(--muted); padding-inline: 9px; }
.button-quiet:hover:not(:disabled) { color: var(--ink); background: var(--surface-warm); }
.button-small { min-height: 36px; padding: 7px 12px; font-size: 11px; }

.intro-band, .signal-summary, .control-deck, .workspace, .footer { width: min(1440px, calc(100% - 40px)); margin-inline: auto; }
.intro-band { padding: clamp(48px, 7vw, 90px) 0 38px; display: flex; justify-content: space-between; align-items: end; gap: 40px; }
.eyebrow, .control-label, .summary-label, .panel-note, .control-subhead, .detail-grid dt, .detail-timestamp, .footer-method .eyebrow { margin: 0; color: var(--muted); font-size: 10px; font-weight: 800; letter-spacing: 0.12em; text-transform: uppercase; }
.intro-band .eyebrow { color: var(--signal); }
.intro-band h1 { max-width: 750px; margin: 10px 0 10px; font-family: var(--display); font-size: clamp(44px, 6vw, 82px); font-weight: 500; letter-spacing: -0.055em; line-height: 0.93; }
.intro-copy { max-width: 610px; margin: 0; color: var(--ink-soft); font-size: clamp(15px, 1.3vw, 18px); line-height: 1.55; }
.intro-note { max-width: 260px; padding: 15px 0 0 18px; border-left: 2px solid var(--signal); }
.intro-note strong { display: block; margin: 6px 0 4px; color: var(--ink); font-size: 13px; }
.intro-note span:last-child { display: block; color: var(--muted); font-size: 11px; line-height: 1.5; }

.signal-summary { min-height: 128px; padding: 22px 24px; display: grid; grid-template-columns: minmax(145px, 0.6fr) 1px minmax(330px, 1.5fr) minmax(260px, 1fr); align-items: center; gap: 24px; background: var(--dark); color: #f6f3eb; box-shadow: var(--shadow); }
.summary-count strong { display: block; margin: 4px 0 0; font-family: var(--display); font-size: clamp(44px, 5vw, 66px); font-weight: 500; letter-spacing: -0.06em; line-height: 0.95; color: #f4c88c; }
.summary-label { color: #9eb0aa; }
.summary-subline { display: block; margin-top: 5px; color: #b4c0bb; font-size: 11px; }
.summary-divider { width: 1px; height: 64px; background: rgba(255, 255, 255, 0.15); }
.summary-story { min-width: 0; }
.strongest-link { width: 100%; margin-top: 9px; padding: 0; display: grid; grid-template-columns: auto minmax(0, 1fr) auto; gap: 13px; align-items: center; background: transparent; color: inherit; text-align: left; }
.strongest-link:hover b { color: #f4c88c; }
.magnitude-stamp { min-width: 52px; padding: 8px 6px; display: inline-flex; justify-content: center; background: var(--signal); color: white; font-family: var(--mono); font-size: 16px; font-weight: 500; }
.strongest-link b { display: block; overflow: hidden; color: #f7f4eb; font-size: 14px; font-weight: 700; text-overflow: ellipsis; white-space: nowrap; }
.strongest-link small { display: block; margin-top: 4px; color: #aebcb7; font-size: 11px; }
.arrow-mark { color: #f4c88c; font-size: 19px; }
.summary-empty { display: block; margin-top: 9px; color: #aebcb7; font-size: 12px; }
.summary-legend { display: flex; flex-wrap: wrap; align-items: center; justify-content: end; gap: 8px 13px; color: #bfcbc4; font-size: 10px; }
.summary-legend .summary-label { width: 100%; }
.legend-dot, .legend-ring { width: 11px; height: 11px; display: inline-block; vertical-align: -1px; margin-right: 4px; border-radius: 50%; }
.legend-dot { background: var(--signal-bright); }
.legend-small { width: 7px; height: 7px; }
.legend-ring { border: 2px solid #d0a36a; }

.control-deck { margin-top: 26px; padding: 22px 24px 18px; background: var(--surface); border: 1px solid var(--line); box-shadow: var(--shadow-soft); }
.time-rail { display: flex; align-items: center; gap: 20px; }
.segmented-control { display: flex; min-height: 44px; flex: 1; border: 1px solid var(--line); background: var(--surface-warm); }
.segmented-control button { flex: 1; min-height: 42px; padding: 8px 13px; display: flex; align-items: center; justify-content: center; gap: 8px; background: transparent; color: var(--muted); font-size: 12px; font-weight: 700; border-right: 1px solid var(--line); }
.segmented-control button:last-child { border-right: 0; }
.segmented-control button:hover { color: var(--ink); background: #f8f6f0; }
.segmented-control button.is-active { background: var(--dark); color: #f8f5ed; }
.segmented-control small { color: inherit; opacity: 0.65; font-family: var(--mono); font-size: 10px; }
.control-actions { display: flex; align-items: center; justify-content: end; gap: 5px; margin-top: -44px; }
.control-actions .button-light { margin-right: 6px; }
.action-feedback { color: var(--good); font-size: 11px; font-weight: 700; }
.filter-grid { margin-top: 24px; padding-top: 20px; display: grid; grid-template-columns: 1.15fr 0.95fr 0.8fr 0.9fr 1.15fr 0.95fr; gap: 17px; border-top: 1px solid var(--line); }
.filter-group, .select-control, .place-search, .check-control { min-width: 0; padding: 0; border: 0; }
.filter-group legend, .select-control > span, .place-search > label, .check-control > .control-subhead { display: block; margin-bottom: 8px; color: var(--ink-soft); font-size: 10px; font-weight: 800; letter-spacing: 0.04em; text-transform: uppercase; }
.range-pair { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }
.range-pair label { min-width: 0; display: block; }
.range-pair label > span { display: block; margin-bottom: 3px; color: var(--muted); font-size: 10px; }
.range-pair output { display: block; margin-bottom: 3px; color: var(--ink); font-family: var(--mono); font-size: 11px; }
input[type='range'] { width: 100%; height: 22px; accent-color: var(--signal); }
.number-pair { display: flex; align-items: end; gap: 7px; }
.number-pair label { flex: 1; }
.number-pair label span { display: block; margin-bottom: 3px; color: var(--muted); font-size: 10px; }
.number-pair input, .select-control select, .place-search input { width: 100%; min-height: 38px; padding: 8px 9px; border: 1px solid var(--line); border-radius: 2px; outline: none; background: #f8f6f0; color: var(--ink); font-size: 12px; }
.number-pair input:focus, .select-control select:focus, .place-search input:focus { border-color: var(--dark-soft); box-shadow: 0 0 0 2px rgba(41, 72, 77, 0.13); }
.number-dash { padding-bottom: 10px; color: var(--muted); }
.select-control select { appearance: none; background-image: none; }
.search-row { display: flex; }
.search-row input { min-width: 0; border-right: 0; }
.search-button { width: 40px; flex: 0 0 40px; min-height: 38px; border: 1px solid var(--line); background: var(--dark); color: white; font-size: 18px; }
.field-status { display: block; margin-top: 5px; overflow: hidden; color: var(--muted); font-size: 10px; text-overflow: ellipsis; white-space: nowrap; }
.field-status-good { color: var(--good); }
.field-status-error { color: var(--critical); }
.check-control { display: flex; flex-direction: column; gap: 9px; }
.check-control > .control-subhead { margin-bottom: 0; }
.check-control label { display: flex; align-items: center; gap: 6px; color: var(--ink-soft); font-size: 11px; }
.check-control input { width: 15px; height: 15px; accent-color: var(--signal); }
.active-filters { min-height: 26px; margin-top: 18px; display: flex; align-items: center; flex-wrap: wrap; gap: 7px; }
.active-label { margin-right: 4px; color: var(--muted); font-family: var(--mono); font-size: 10px; }
.no-filters { color: var(--muted-light); font-size: 11px; }
.filter-chip { min-height: 28px; padding: 5px 9px; display: inline-flex; align-items: center; gap: 8px; border: 1px solid #cac5b8; border-radius: 20px; background: #efebe1; color: var(--ink-soft); font-size: 10px; font-weight: 700; }
.filter-chip:hover { border-color: var(--signal); color: var(--signal); }
.filter-chip span { color: var(--signal); font-size: 15px; line-height: 10px; }
.filter-chip-time { border-color: #d6a477; background: #f8eadc; color: #9c5338; }

.workspace { margin-top: 26px; display: grid; grid-template-columns: minmax(0, 1.65fr) minmax(340px, 0.75fr); gap: 26px; align-items: start; }
.map-column { min-width: 0; display: flex; flex-direction: column; gap: 22px; }
.map-panel, .timeline-panel, .depth-panel, .stream-panel, .inspector { background: var(--surface); border: 1px solid var(--line); box-shadow: var(--shadow-soft); }
.map-panel { overflow: hidden; }
.panel-heading { min-height: 72px; padding: 20px 22px; display: flex; justify-content: space-between; align-items: center; gap: 16px; }
.panel-heading h2 { margin: 4px 0 0; font-family: var(--display); font-size: 25px; font-weight: 500; letter-spacing: -0.035em; line-height: 1; }
.map-heading-actions { display: flex; align-items: center; gap: 11px; }
.map-zoom { color: var(--muted); font-family: var(--mono); font-size: 10px; }
.icon-button { width: 38px; height: 38px; border: 1px solid var(--line); background: var(--surface-warm); color: var(--ink); font-size: 20px; }
.icon-button:hover { background: var(--dark); color: white; }
.map-frame { min-height: 500px; position: relative; background: #d9ded9; border-top: 1px solid var(--line); border-bottom: 1px solid var(--line); }
.map-container { width: 100%; height: 550px; z-index: 1; }
.map-key { position: absolute; z-index: 450; left: 14px; bottom: 14px; padding: 9px 11px; display: flex; flex-wrap: wrap; gap: 8px 13px; background: rgba(250, 248, 241, 0.94); border: 1px solid rgba(23, 37, 42, 0.16); color: var(--ink-soft); font-size: 10px; box-shadow: 0 5px 16px rgba(23, 37, 42, 0.1); }
.map-key span { display: inline-flex; align-items: center; gap: 5px; }
.key-swatch { width: 10px; height: 10px; display: inline-block; border-radius: 50%; }
.key-low { background: var(--teal); }
.key-high { width: 15px; height: 15px; background: var(--signal); }
.key-outline { width: 13px; height: 10px; display: inline-block; border: 2px dashed var(--dark); border-radius: 50%; }
.map-caption { min-height: 38px; padding: 9px 16px; display: flex; justify-content: space-between; gap: 14px; color: var(--muted); font-size: 10px; }
.map-attribution { color: var(--muted-light); white-space: nowrap; }
.map-loading, .map-error, .map-empty { position: absolute; z-index: 500; left: 50%; top: 50%; transform: translate(-50%, -50%); box-shadow: var(--shadow); }
.map-loading { width: min(340px, calc(100% - 30px)); padding: 13px 15px; display: flex; align-items: center; gap: 11px; background: rgba(26, 43, 46, 0.94); color: #f4f1e9; font-size: 12px; }
.loader-line { width: 24px; height: 3px; display: inline-block; background: var(--signal-bright); animation: pulse-line 1.15s ease-in-out infinite alternate; }
@keyframes pulse-line { from { transform: scaleX(0.45); transform-origin: left; } to { transform: scaleX(1); transform-origin: left; } }
.map-error { width: min(420px, calc(100% - 30px)); padding: 18px; display: grid; grid-template-columns: 1fr auto; gap: 5px 15px; background: #fff5e9; border: 1px solid #d7a276; color: var(--ink); }
.map-error strong { font-size: 13px; }
.map-error span { grid-column: 1 / -1; color: var(--muted); font-size: 11px; }
.map-error .button { grid-column: 2; grid-row: 1 / span 2; align-self: center; }
.map-empty { width: min(310px, calc(100% - 30px)); padding: 28px; display: flex; flex-direction: column; align-items: center; gap: 8px; text-align: center; background: rgba(250, 248, 241, 0.96); border: 1px solid var(--line); }
.empty-glyph { color: var(--signal); font-family: var(--display); font-size: 38px; line-height: 1; }
.map-empty strong, .inspector-empty h2 { font-family: var(--display); font-size: 23px; font-weight: 500; }
.map-empty span:not(.empty-glyph), .inspector-empty p { color: var(--muted); font-size: 11px; }
.map-empty .button { margin-top: 8px; }
.leaflet-container { font-family: var(--body); background: #d9ded9; }
.leaflet-control-zoom { border: 1px solid rgba(23, 37, 42, 0.18) !important; box-shadow: 0 4px 14px rgba(23, 37, 42, 0.1) !important; }
.leaflet-control-zoom a { width: 32px !important; height: 32px !important; line-height: 30px !important; color: var(--ink) !important; background: rgba(250, 248, 241, 0.95) !important; }
.leaflet-control-zoom a:hover { background: var(--dark) !important; color: white !important; }
.leaflet-control-attribution { background: rgba(250, 248, 241, 0.8) !important; color: var(--muted) !important; font-size: 8px !important; }
.leaflet-control-attribution a { color: var(--ink-soft) !important; }
.quake-cluster-icon { background: transparent; border: 0; }
.quake-cluster { width: 56px; height: 56px; display: flex; flex-direction: column; justify-content: center; align-items: center; border: 2px solid rgba(26, 43, 46, 0.72); border-radius: 50%; background: rgba(196, 111, 77, 0.82); color: white; box-shadow: 0 0 0 4px rgba(250, 248, 241, 0.65), 0 4px 12px rgba(23, 37, 42, 0.24); }
.quake-cluster b { font-family: var(--mono); font-size: 15px; line-height: 1; }
.quake-cluster small { margin-top: 3px; font-size: 9px; }
.quake-cluster-large { width: 64px; height: 64px; background: rgba(173, 64, 55, 0.9); }
.quake-marker-muted { opacity: 0.4; }

.timeline-panel { overflow: hidden; }
.timeline-heading { padding-bottom: 11px; }
.timeline-meta { display: flex; align-items: center; gap: 12px; color: var(--muted); font-size: 11px; text-align: right; }
.text-button { padding: 4px 0; background: transparent; color: var(--signal); font-size: 11px; font-weight: 800; }
.text-button:hover { text-decoration: underline; }
.timeline-chart-wrap { position: relative; padding: 0 15px 3px; border-top: 1px solid var(--line); }
.timeline-chart { width: 100%; height: auto; min-height: 175px; overflow: visible; }
.chart-baseline { stroke: #88938c; stroke-width: 1; }
.chart-gridline { stroke: #dedbd1; stroke-width: 1; stroke-dasharray: 3 4; }
.chart-axis-label, .chart-x-label { fill: var(--muted); font-family: var(--mono); font-size: 10px; }
.timeline-hit-area { fill: transparent; cursor: pointer; }
.timeline-hit-area:hover, .timeline-hit-area:focus-visible { fill: rgba(201, 87, 67, 0.1); outline: none; }
.timeline-hit-selected { fill: rgba(201, 87, 67, 0.12); }
.timeline-bar { fill: var(--teal); pointer-events: none; opacity: 0.86; }
.timeline-bar-selected { fill: var(--signal); }
.timeline-bar-empty { fill: #d3d7d1; opacity: 0.65; }
.timeline-cap { fill: var(--signal-bright); pointer-events: none; }
.timeline-focus-line { stroke: var(--ink); stroke-width: 1.5; stroke-dasharray: 4 4; pointer-events: none; }
.timeline-tooltip { position: absolute; top: 10px; min-width: 175px; padding: 8px 10px; transform: translateX(-50%); pointer-events: none; background: var(--dark); color: #f6f3eb; box-shadow: var(--shadow-soft); font-size: 10px; }
.timeline-tooltip b, .timeline-tooltip span { display: block; }
.timeline-tooltip b { color: #f4c88c; font-family: var(--mono); font-size: 10px; }
.timeline-tooltip span { margin-top: 3px; color: #ccd3cd; }
.timeline-reading { padding: 0 22px 17px; display: flex; flex-wrap: wrap; align-items: center; gap: 12px 20px; color: var(--muted); font-size: 10px; }
.timeline-reading-key { display: inline-flex; align-items: center; gap: 6px; }
.timeline-reading-key i { width: 12px; height: 8px; display: inline-block; border-radius: 2px; }
.timeline-key-volume { background: var(--teal); }
.timeline-key-peak { height: 4px !important; background: var(--signal-bright); }
.timeline-reading-note { margin-left: auto; color: var(--muted-light); }

.depth-panel { padding-bottom: 18px; }
.depth-panel .panel-heading { min-height: 62px; padding-bottom: 14px; }
.depth-distribution { padding: 0 22px; display: grid; grid-template-columns: repeat(4, 1fr); gap: 8px; }
.depth-band { min-width: 0; padding: 11px 10px; display: grid; grid-template-columns: 1fr auto; gap: 9px 7px; align-items: center; background: var(--surface-warm); border: 1px solid transparent; text-align: left; }
.depth-band:hover, .depth-band.is-active { background: #f7e8dd; border-color: #d7956f; }
.depth-band-copy b, .depth-band-copy small { display: block; }
.depth-band-copy b { font-size: 11px; }
.depth-band-copy small { margin-top: 2px; color: var(--muted); font-size: 9px; }
.depth-band > strong { color: var(--ink-soft); font-family: var(--mono); font-size: 11px; }
.depth-track { grid-column: 1 / -1; height: 6px; background: #d2d8d1; }
.depth-track i { height: 100%; display: block; min-width: 2px; background: var(--teal); }
.depth-band.is-active .depth-track i { background: var(--signal); }

.stream-panel { overflow: hidden; }
.stream-heading { min-height: 70px; }
.stream-total { text-align: right; }
.stream-total strong { display: block; font-family: var(--mono); font-size: 18px; font-weight: 500; }
.stream-total span { display: block; color: var(--muted); font-size: 10px; }
.stream-context { padding: 9px 22px; background: #f8e9de; border-top: 1px solid #e5c8b3; border-bottom: 1px solid #e5c8b3; color: #95573d; font-size: 11px; }
.event-list { border-top: 1px solid var(--line); }
.event-row { width: 100%; min-height: 74px; padding: 13px 22px; display: grid; grid-template-columns: 58px minmax(0, 1fr) auto 18px; align-items: center; gap: 14px; background: var(--surface); border-bottom: 1px solid var(--line); color: var(--ink); text-align: left; position: relative; }
.event-row:hover, .event-row:focus-visible { background: #f7f3e9; }
.event-row.is-selected { background: #f8e9de; box-shadow: inset 4px 0 0 var(--signal); }
.event-row.is-out-window:not(.is-selected) { opacity: 0.42; }
.event-row.is-in-window:not(.is-selected) { box-shadow: inset 3px 0 0 #daa16e; }
.event-magnitude { width: 50px; padding: 8px 5px; display: inline-flex; justify-content: center; background: #e8e4d9; color: var(--ink); font-family: var(--mono); font-size: 12px; font-weight: 500; }
.event-row.is-selected .event-magnitude { background: var(--signal); color: white; }
.event-row-main { min-width: 0; }
.event-row-main strong, .event-row-main span { display: block; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.event-row-main strong { font-size: 12px; font-weight: 800; }
.event-row-main span { margin-top: 5px; color: var(--muted); font-size: 10px; }
.event-row-tags { display: flex; justify-content: end; flex-wrap: wrap; gap: 5px; }
.tag { padding: 4px 6px; border-radius: 2px; color: var(--ink-soft); background: #e7ebe5; font-size: 9px; font-style: normal; font-weight: 800; white-space: nowrap; }
.tag-tsunami { background: #f5e3d2; color: #955438; }
.tag-reviewed { background: #e1ede5; color: #477362; }
.alert-green { background: #dcebe2; color: #477362; }
.alert-yellow { background: #f2e7c8; color: #88651f; }
.alert-orange { background: #f4ddd0; color: #9a4c35; }
.alert-red { background: #f1d1d0; color: #8d2929; }
.alert-unknown { background: #e8ebe7; color: var(--muted); }
.event-row-arrow { color: var(--signal); font-size: 12px; text-align: right; }
.load-more { width: calc(100% - 44px); min-height: 44px; margin: 16px 22px 8px; background: var(--surface-warm); color: var(--ink-soft); font-size: 11px; font-weight: 800; }
.load-more:hover { background: #e8e3d8; }
.load-more span { margin-left: 4px; color: var(--muted); font-weight: 500; }
.stream-empty { min-height: 150px; padding: 30px 22px; display: flex; flex-direction: column; align-items: flex-start; justify-content: center; gap: 7px; border-top: 1px solid var(--line); }
.stream-empty strong { font-family: var(--display); font-size: 21px; font-weight: 500; }
.stream-empty span { color: var(--muted); font-size: 11px; }
.stream-empty .button { margin-top: 7px; }
.stream-footnote { margin: 0; padding: 13px 22px 17px; color: var(--muted-light); font-size: 10px; }

.inspector { position: sticky; top: 18px; overflow: hidden; }
.inspector-topline { padding: 18px 22px 0; display: flex; justify-content: space-between; }
.dossier-index { color: var(--signal); font-family: var(--mono); font-size: 11px; }
.inspector-title-row { padding: 24px 22px 0; display: flex; justify-content: space-between; gap: 16px; align-items: start; }
.magnitude-hero { display: block; color: var(--signal); font-family: var(--mono); font-size: 41px; font-weight: 500; letter-spacing: -0.07em; line-height: 0.9; }
.inspector h2 { max-width: 320px; margin: 11px 0 0; font-family: var(--display); font-size: clamp(28px, 2.3vw, 38px); font-weight: 500; letter-spacing: -0.05em; line-height: 0.98; }
.status-seal { min-width: 74px; padding: 8px 7px; display: inline-flex; align-items: center; justify-content: center; gap: 5px; color: var(--muted); background: #e8ebe7; font-size: 9px; font-weight: 800; text-transform: uppercase; }
.status-seal i { width: 7px; height: 7px; display: inline-block; border-radius: 50%; background: currentColor; }
.status-seal.alert-green { background: #dcebe2; color: #477362; }
.status-seal.alert-yellow { background: #f2e7c8; color: #88651f; }
.status-seal.alert-orange { background: #f4ddd0; color: #9a4c35; }
.status-seal.alert-red { background: #f1d1d0; color: #8d2929; }
.detail-lede { margin: 14px 22px 0; color: var(--muted); font-size: 11px; line-height: 1.5; }
.detail-actions { padding: 19px 22px; display: flex; flex-wrap: wrap; gap: 8px; }
.detail-actions .button { flex: 1; min-width: 135px; }
.detail-grid { margin: 0; display: grid; grid-template-columns: 1fr 1fr; border-top: 1px solid var(--line); }
.detail-grid > div { min-width: 0; padding: 15px 17px; border-bottom: 1px solid var(--line); }
.detail-grid > div:nth-child(odd) { border-right: 1px solid var(--line); }
.detail-grid dt { color: var(--muted); font-family: var(--mono); font-size: 9px; letter-spacing: 0.04em; }
.detail-grid dd { margin: 5px 0 0; overflow: hidden; color: var(--ink); font-size: 12px; font-weight: 800; text-overflow: ellipsis; white-space: nowrap; }
.detail-grid small { display: block; margin-top: 3px; color: var(--muted-light); font-size: 9px; line-height: 1.35; }
.detail-note { margin: 18px 22px; padding: 12px; display: flex; gap: 10px; border-left: 2px solid var(--amber); background: #f2eee3; }
.note-symbol { width: 18px; height: 18px; flex: 0 0 18px; display: inline-flex; align-items: center; justify-content: center; border: 1px solid var(--amber); border-radius: 50%; color: #8d6b2a; font-family: var(--mono); font-size: 10px; }
.detail-note p { margin: 0; color: var(--ink-soft); font-size: 10px; line-height: 1.55; }
.detail-note strong { color: var(--ink); }
.detail-timestamp { padding: 13px 22px 18px; display: flex; flex-direction: column; gap: 3px; border-top: 1px solid var(--line); font-family: var(--mono); font-size: 9px; letter-spacing: 0; text-transform: none; }
.inspector-empty { min-height: 360px; padding: 55px 25px; display: flex; flex-direction: column; align-items: center; justify-content: center; text-align: center; }
.inspector-empty h2 { margin: 12px 0 0; }
.inspector-empty p { max-width: 220px; }

.footer { margin-top: 34px; padding: 32px 0 42px; display: grid; grid-template-columns: 1fr 1fr auto; gap: 30px; border-top: 1px solid var(--line-strong); color: var(--muted); }
.footer .brand-name { color: var(--ink); }
.footer p { max-width: 400px; margin: 9px 0 0; font-size: 11px; line-height: 1.55; }
.footer-method { max-width: 440px; }
.footer-mark { color: var(--signal); font-family: var(--display); font-size: 36px; align-self: center; }

@media (max-width: 1120px) {
  .topnav { display: none; }
  .filter-grid { grid-template-columns: repeat(3, 1fr); }
  .workspace { grid-template-columns: minmax(0, 1.4fr) minmax(310px, 0.8fr); }
  .summary-legend { justify-content: start; }
}

@media (max-width: 900px) {
  .topbar { padding-inline: 20px; }
  .top-actions { margin-left: auto; }
  .top-actions .connection-status { display: none; }
  .intro-band { padding-top: 50px; flex-direction: column; align-items: flex-start; }
  .intro-note { max-width: 380px; }
  .signal-summary { grid-template-columns: 0.7fr 1px 1.3fr; }
  .summary-legend { display: none; }
  .workspace { grid-template-columns: 1fr; }
  .inspector { position: static; grid-row: 2; }
  .map-column { grid-row: 1; }
  .map-container { height: 500px; }
  .depth-distribution { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 640px) {
  body { font-size: 13px; }
  .topbar { min-height: 67px; padding: 12px 15px; gap: 10px; }
  .brand-caption { display: none; }
  .brand-name { font-size: 10px; }
  .brand-mark { width: 23px; height: 29px; }
  .top-actions .button { padding-inline: 10px; }
  .intro-band, .signal-summary, .control-deck, .workspace, .footer { width: min(100% - 24px, 1440px); }
  .intro-band { padding-top: 39px; padding-bottom: 26px; gap: 26px; }
  .intro-band h1 { font-size: clamp(42px, 15vw, 66px); }
  .intro-copy { font-size: 14px; }
  .intro-note { padding-left: 13px; }
  .signal-summary { min-height: 0; padding: 18px 16px; grid-template-columns: 1fr; gap: 15px; }
  .summary-divider { width: 100%; height: 1px; }
  .summary-count strong { font-size: 50px; }
  .control-deck { margin-top: 17px; padding: 17px 14px 14px; }
  .time-rail { display: block; }
  .time-rail .control-label { display: block; margin-bottom: 9px; }
  .segmented-control { overflow-x: auto; }
  .segmented-control button { min-width: 94px; padding-inline: 8px; flex: 0 0 auto; }
  .segmented-control button span { font-size: 11px; }
  .control-actions { margin-top: 14px; justify-content: space-between; }
  .control-actions .button-light { margin-right: 0; }
  .filter-grid { grid-template-columns: 1fr 1fr; gap: 17px 12px; }
  .magnitude-filter, .place-search { grid-column: 1 / -1; }
  .active-filters { align-items: flex-start; }
  .workspace { margin-top: 17px; gap: 17px; }
  .map-column { gap: 17px; }
  .panel-heading { min-height: 65px; padding: 17px 15px; }
  .panel-heading h2 { font-size: 23px; }
  .map-heading-actions { gap: 7px; }
  .map-zoom { display: none; }
  .map-frame { min-height: 430px; }
  .map-container { height: 430px; }
  .map-key { left: 8px; right: 8px; bottom: 8px; gap: 6px 10px; }
  .map-caption { padding: 8px 12px; flex-direction: column; gap: 4px; }
  .map-attribution { white-space: normal; }
  .timeline-heading { display: block; }
  .timeline-meta { margin-top: 10px; text-align: left; }
  .timeline-chart-wrap { padding-inline: 6px; }
  .timeline-reading { padding-inline: 15px; gap: 9px 14px; }
  .timeline-reading-note { width: 100%; margin-left: 0; }
  .depth-distribution { padding-inline: 15px; gap: 7px; }
  .depth-band { padding: 10px 8px; }
  .stream-heading { padding-inline: 15px; }
  .stream-context { padding-inline: 15px; }
  .event-row { padding-inline: 15px; grid-template-columns: 52px minmax(0, 1fr) 14px; gap: 10px; }
  .event-row-tags { grid-column: 2 / 3; justify-content: start; }
  .event-row-arrow { grid-column: 3; grid-row: 1 / span 2; }
  .event-magnitude { width: 47px; }
  .stream-footnote { padding-inline: 15px; }
  .inspector-title-row { padding-inline: 17px; }
  .inspector-topline { padding-inline: 17px; }
  .detail-lede, .detail-actions, .detail-note, .detail-timestamp { margin-left: 17px; margin-right: 17px; }
  .detail-actions { padding-inline: 0; }
  .detail-grid > div { padding: 13px 12px; }
  .detail-grid dd { font-size: 11px; }
  .footer { grid-template-columns: 1fr; gap: 20px; padding-bottom: 30px; }
  .footer-mark { display: none; }
}

@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  *, *::before, *::after { animation-duration: 0.001ms !important; animation-iteration-count: 1 !important; transition-duration: 0.001ms !important; }
}

@media (forced-colors: active) {
  .event-row.is-selected, .event-row.is-in-window:not(.is-selected) { outline: 2px solid CanvasText; box-shadow: none; }
  .timeline-bar, .timeline-cap, .depth-track i { forced-color-adjust: none; background: Highlight; }
  .button, .filter-chip, .depth-band { border: 1px solid ButtonText; }
}

tool_use_result.content:
@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Manrope:wght@400;500;600;700;800&family=Newsreader:opsz,wght@6..72,500;6..72,600&display=swap');

:root {
  --ink: #17252a;
  --ink-soft: #314044;
  --muted: #687370;
  --muted-light: #89928c;
  --paper: #f4f1e9;
  --paper-deep: #e9e5db;
  --surface: #fbf9f3;
  --surface-warm: #f0ede4;
  --line: #d3d0c6;
  --line-strong: #aeb5ad;
  --dark: #1a2b2e;
  --dark-soft: #284247;
  --signal: #c95743;
  --signal-bright: #dd7454;
  --amber: #b7924f;
  --teal: #6c918b;
  --good: #5d8678;
  --warning: #bd8b34;
  --serious: #bb643d;
  --critical: #9d3030;
  --shadow: 0 20px 55px rgba(29, 43, 43, 0.09);
  --shadow-soft: 0 8px 24px rgba(29, 43, 43, 0.07);
  --display: 'Newsreader', 'Iowan Old Style', 'Palatino Linotype', Georgia, serif;
  --body: 'Manrope', 'Avenir Next', Avenir, Helvetica, Arial, sans-serif;
  --mono: 'DM Mono', 'SFMono-Regular', Consolas, monospace;
}

* { box-sizing: border-box; }

html { scroll-behavior: smooth; }

body {
  margin: 0;
  min-width: 320px;
  background: var(--paper-deep);
  color: var(--ink);
  font-family: var(--body);
  font-size: 14px;
  line-height: 1.45;
  -webkit-font-smoothing: antialiased;
}

button, input, select { font: inherit; }
button, a { -webkit-tap-highlight-color: transparent; }
button { cursor: pointer; }
button:disabled { cursor: not-allowed; opacity: 0.5; }
a { color: inherit; }

:focus-visible {
  outline: 3px solid var(--signal-bright);
  outline-offset: 3px;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.app-shell {
  min-height: 100vh;
  background: var(--paper);
  overflow: clip;
}

.topbar {
  min-height: 76px;
  padding: 16px clamp(20px, 4vw, 64px);
  display: flex;
  align-items: center;
  gap: 32px;
  background: var(--dark);
  color: #f7f4eb;
  border-bottom: 1px solid rgba(255, 255, 255, 0.12);
}

.brand-lockup {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  text-decoration: none;
  min-width: max-content;
}

.brand-mark {
  width: 28px;
  height: 34px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 3px;
  border-left: 1px solid rgba(255, 255, 255, 0.35);
  border-right: 1px solid rgba(255, 255, 255, 0.35);
  transform: skewX(-9deg);
}

.brand-mark i {
  display: block;
  width: 2px;
  background: var(--signal-bright);
  border-radius: 4px;
  transform: skewX(9deg);
}

.brand-mark i:nth-child(1) { height: 12px; }
.brand-mark i:nth-child(2) { height: 25px; background: #e4b66f; }
.brand-mark i:nth-child(3) { height: 17px; }

.brand-name, .brand-caption { display: block; }
.brand-name { font-size: 12px; font-weight: 800; letter-spacing: 0.08em; text-transform: uppercase; }
.brand-caption { margin-top: 2px; color: #aebbb7; font-size: 10px; letter-spacing: 0.02em; }

.topnav { display: flex; align-items: center; gap: 24px; margin-left: auto; }
.topnav a { color: #c8d1cb; font-size: 12px; text-decoration: none; }
.topnav a:hover { color: #fff; }

.top-actions { display: flex; align-items: center; gap: 13px; }
.connection-status { display: inline-flex; align-items: center; gap: 7px; color: #a6d3b9; font-size: 11px; font-weight: 700; letter-spacing: 0.03em; white-space: nowrap; }
