                {depthBuckets.map((band) => <button key={band.label} type="button" role="listitem" className={`depth-band ${depthMin === band.min && (band.max === MAX_DEPTH ? depthMax === MAX_DEPTH : depthMax === band.max) ? 'is-active' : ''}`} onClick={() => { setDepthMin(band.min); setDepthMax(band.max); }} aria-label={`${band.label}, ${band.sublabel}, ${band.count} events`}><span className="depth-band-copy"><b>{band.label}</b><small>{band.sublabel}</small></span><span className="depth-track"><i style={{ width: `${Math.max(2, (band.count / maxDepthCount) * 100)}%` }} /></span><strong>{formatNumber(band.count)}</strong></button>)}
