@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Manrope:wght@400;500;600;700;800&family=Newsreader:opsz,wght@6..72,500;6..72,600&display=swap');

:root {
  --ink: #17252a;
  --ink-soft: #314044;
  --muted: #687370;
  --muted-light: #89928c;
  --paper: #f4f1e9;
  --paper-deep: #e9e5db;
  --surface: #fbf9f3;
  --surface-warm: #f0ede4;
  --line: #d3d0c6;
  --line-strong: #aeb5ad;
  --dark: #1a2b2e;
  --dark-soft: #284247;
  --signal: #c95743;
  --signal-bright: #dd7454;
  --amber: #b7924f;
  --teal: #6c918b;
  --good: #5d8678;
  --warning: #bd8b34;
  --serious: #bb643d;
  --critical: #9d3030;
  --shadow: 0 20px 55px rgba(29, 43, 43, 0.09);
  --shadow-soft: 0 8px 24px rgba(29, 43, 43, 0.07);
  --display: 'Newsreader', 'Iowan Old Style', 'Palatino Linotype', Georgia, serif;
  --body: 'Manrope', 'Avenir Next', Avenir, Helvetica, Arial, sans-serif;
  --mono: 'DM Mono', 'SFMono-Regular', Consolas, monospace;
}

* { box-sizing: border-box; }

html { scroll-behavior: smooth; }

body {
  margin: 0;
  min-width: 320px;
  background: var(--paper-deep);
  color: var(--ink);
  font-family: var(--body);
  font-size: 14px;
  line-height: 1.45;
  -webkit-font-smoothing: antialiased;
}

button, input, select { font: inherit; }
button, a { -webkit-tap-highlight-color: transparent; }
button { cursor: pointer; }
button:disabled { cursor: not-allowed; opacity: 0.5; }
a { color: inherit; }

:focus-visible {
  outline: 3px solid var(--signal-bright);
  outline-offset: 3px;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.app-shell {
  min-height: 100vh;
  background: var(--paper);
  overflow: clip;
}

.topbar {
  min-height: 76px;
  padding: 16px clamp(20px, 4vw, 64px);
  display: flex;
  align-items: center;
  gap: 32px;
  background: var(--dark);
  color: #f7f4eb;
  border-bottom: 1px solid rgba(255, 255, 255, 0.12);
}

.brand-lockup {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  text-decoration: none;
  min-width: max-content;
}

.brand-mark {
  width: 28px;
  height: 34px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 3px;
  border-left: 1px solid rgba(255, 255, 255, 0.35);
  border-right: 1px solid rgba(255, 255, 255, 0.35);
  transform: skewX(-9deg);
}

.brand-mark i {
  display: block;
  width: 2px;
  background: var(--signal-bright);
  border-radius: 4px;
  transform: skewX(9deg);
}

.brand-mark i:nth-child(1) { height: 12px; }
.brand-mark i:nth-child(2) { height: 25px; background: #e4b66f; }
.brand-mark i:nth-child(3) { height: 17px; }

.brand-name, .brand-caption { display: block; }
.brand-name { font-size: 12px; font-weight: 800; letter-spacing: 0.08em; text-transform: uppercase; }
.brand-caption { margin-top: 2px; color: #aebbb7; font-size: 10px; letter-spacing: 0.02em; }

.topnav { display: flex; align-items: center; gap: 24px; margin-left: auto; }
.topnav a { color: #c8d1cb; font-size: 12px; text-decoration: none; }
.topnav a:hover { color: #fff; }

.top-actions { display: flex; align-items: center; gap: 13px; }
.connection-status { display: inline-flex; align-items: center; gap: 7px; color: #a6d3b9; font-size: 11px; font-weight: 700; letter-spacing: 0.03em; white-space: nowrap; }
.connection-status.status-stale { color: #e5b481; }
.status-dot { width: 7px; height: 7px; display: inline-block; border-radius: 50%; background: #7bc492; box-shadow: 0 0 0 3px rgba(123, 196, 146, 0.13); }
.status-stale .status-dot { background: #e5a25f; box-shadow: 0 0 0 3px rgba(229, 162, 95, 0.14); }

.button, .icon-button, .text-button, .load-more, .filter-chip, .segmented-control button, .event-row, .depth-band, .strongest-link, .search-button { border: 0; }
.button { min-height: 44px; padding: 10px 15px; display: inline-flex; align-items: center; justify-content: center; gap: 8px; border-radius: 4px; font-size: 12px; font-weight: 800; letter-spacing: 0.01em; text-decoration: none; transition: background-color 160ms ease, color 160ms ease, border-color 160ms ease, transform 160ms ease; }
.button:hover:not(:disabled) { transform: translateY(-1px); }
.button-dark { background: var(--dark); color: #fff; }
.button-dark:hover:not(:disabled) { background: #29484d; }
.topbar .button-dark { background: #f4f1e9; color: var(--dark); }
.topbar .button-dark:hover:not(:disabled) { background: #fff; }
.button-light { background: var(--surface); color: var(--ink); border: 1px solid var(--line); }
.button-light:hover:not(:disabled) { background: #fff; border-color: var(--line-strong); }
.button-quiet { background: transparent; color: var(--muted); padding-inline: 9px; }
.button-quiet:hover:not(:disabled) { color: var(--ink); background: var(--surface-warm); }
.button-small { min-height: 36px; padding: 7px 12px; font-size: 11px; }

.intro-band, .signal-summary, .control-deck, .workspace, .footer { width: min(1440px, calc(100% - 40px)); margin-inline: auto; }
.intro-band { padding: clamp(48px, 7vw, 90px) 0 38px; display: flex; justify-content: space-between; align-items: end; gap: 40px; }
.eyebrow, .control-label, .summary-label, .panel-note, .control-subhead, .detail-grid dt, .detail-timestamp, .footer-method .eyebrow { margin: 0; color: var(--muted); font-size: 10px; font-weight: 800; letter-spacing: 0.12em; text-transform: uppercase; }
.intro-band .eyebrow { color: var(--signal); }
.intro-band h1 { max-width: 750px; margin: 10px 0 10px; font-family: var(--display); font-size: clamp(44px, 6vw, 82px); font-weight: 500; letter-spacing: -0.055em; line-height: 0.93; }
.intro-copy { max-width: 610px; margin: 0; color: var(--ink-soft); font-size: clamp(15px, 1.3vw, 18px); line-height: 1.55; }
.intro-note { max-width: 260px; padding: 15px 0 0 18px; border-left: 2px solid var(--signal); }
.intro-note strong { display: block; margin: 6px 0 4px; color: var(--ink); font-size: 13px; }
.intro-note span:last-child { display: block; color: var(--muted); font-size: 11px; line-height: 1.5; }

.signal-summary { min-height: 128px; padding: 22px 24px; display: grid; grid-template-columns: minmax(145px, 0.6fr) 1px minmax(330px, 1.5fr) minmax(260px, 1fr); align-items: center; gap: 24px; background: var(--dark); color: #f6f3eb; box-shadow: var(--shadow); }
.summary-count strong { display: block; margin: 4px 0 0; font-family: var(--display); font-size: clamp(44px, 5vw, 66px); font-weight: 500; letter-spacing: -0.06em; line-height: 0.95; color: #f4c88c; }
.summary-label { color: #9eb0aa; }
.summary-subline { display: block; margin-top: 5px; color: #b4c0bb; font-size: 11px; }
.summary-divider { width: 1px; height: 64px; background: rgba(255, 255, 255, 0.15); }
.summary-story { min-width: 0; }
.strongest-link { width: 100%; margin-top: 9px; padding: 0; display: grid; grid-template-columns: auto minmax(0, 1fr) auto; gap: 13px; align-items: center; background: transparent; color: inherit; text-align: left; }
.strongest-link:hover b { color: #f4c88c; }
.magnitude-stamp { min-width: 52px; padding: 8px 6px; display: inline-flex; justify-content: center; background: var(--signal); color: white; font-family: var(--mono); font-size: 16px; font-weight: 500; }
.strongest-link b { display: block; overflow: hidden; color: #f7f4eb; font-size: 14px; font-weight: 700; text-overflow: ellipsis; white-space: nowrap; }
.strongest-link small { display: block; margin-top: 4px; color: #aebcb7; font-size: 11px; }
.arrow-mark { color: #f4c88c; font-size: 19px; }
.summary-empty { display: block; margin-top: 9px; color: #aebcb7; font-size: 12px; }
.summary-legend { display: flex; flex-wrap: wrap; align-items: center; justify-content: end; gap: 8px 13px; color: #bfcbc4; font-size: 10px; }
.summary-legend .summary-label { width: 100%; }
.legend-dot, .legend-ring { width: 11px; height: 11px; display: inline-block; vertical-align: -1px; margin-right: 4px; border-radius: 50%; }
.legend-dot { background: var(--signal-bright); }
.legend-small { width: 7px; height: 7px; }
.legend-ring { border: 2px solid #d0a36a; }

.control-deck { margin-top: 26px; padding: 22px 24px 18px; background: var(--surface); border: 1px solid var(--line); box-shadow: var(--shadow-soft); }
.time-rail { display: flex; align-items: center; gap: 20px; }
.segmented-control { display: flex; min-height: 44px; flex: 1; border: 1px solid var(--line); background: var(--surface-warm); }
.segmented-control button { flex: 1; min-height: 42px; padding: 8px 13px; display: flex; align-items: center; justify-content: center; gap: 8px; background: transparent; color: var(--muted); font-size: 12px; font-weight: 700; border-right: 1px solid var(--line); }
.segmented-control button:last-child { border-right: 0; }
.segmented-control button:hover { color: var(--ink); background: #f8f6f0; }
.segmented-control button.is-active { background: var(--dark); color: #f8f5ed; }
.segmented-control small { color: inherit; opacity: 0.65; font-family: var(--mono); font-size: 10px; }
.control-actions { display: flex; align-items: center; justify-content: end; gap: 5px; margin-top: -44px; }
.control-actions .button-light { margin-right: 6px; }
.action-feedback { color: var(--good); font-size: 11px; font-weight: 700; }
.filter-grid { margin-top: 24px; padding-top: 20px; display: grid; grid-template-columns: 1.15fr 0.95fr 0.8fr 0.9fr 1.15fr 0.95fr; gap: 17px; border-top: 1px solid var(--line); }
.filter-group, .select-control, .place-search, .check-control { min-width: 0; padding: 0; border: 0; }
.filter-group legend, .select-control > span, .place-search > label, .check-control > .control-subhead { display: block; margin-bottom: 8px; color: var(--ink-soft); font-size: 10px; font-weight: 800; letter-spacing: 0.04em; text-transform: uppercase; }
.range-pair { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }
.range-pair label { min-width: 0; display: block; }
.range-pair label > span { display: block; margin-bottom: 3px; color: var(--muted); font-size: 10px; }
.range-pair output { display: block; margin-bottom: 3px; color: var(--ink); font-family: var(--mono); font-size: 11px; }
input[type='range'] { width: 100%; height: 22px; accent-color: var(--signal); }
.number-pair { display: flex; align-items: end; gap: 7px; }
.number-pair label { flex: 1; }
.number-pair label span { display: block; margin-bottom: 3px; color: var(--muted); font-size: 10px; }
.number-pair input, .select-control select, .place-search input { width: 100%; min-height: 38px; padding: 8px 9px; border: 1px solid var(--line); border-radius: 2px; outline: none; background: #f8f6f0; color: var(--ink); font-size: 12px; }
.number-pair input:focus, .select-control select:focus, .place-search input:focus { border-color: var(--dark-soft); box-shadow: 0 0 0 2px rgba(41, 72, 77, 0.13); }
.number-dash { padding-bottom: 10px; color: var(--muted); }
.select-control select { appearance: none; background-image: none; }
.search-row { display: flex; }
.search-row input { min-width: 0; border-right: 0; }
.search-button { width: 40px; flex: 0 0 40px; min-height: 38px; border: 1px solid var(--line); background: var(--dark); color: white; font-size: 18px; }
.field-status { display: block; margin-top: 5px; overflow: hidden; color: var(--muted); font-size: 10px; text-overflow: ellipsis; white-space: nowrap; }
.field-status-good { color: var(--good); }
.field-status-error { color: var(--critical); }
.check-control { display: flex; flex-direction: column; gap: 9px; }
.check-control > .control-subhead { margin-bottom: 0; }
.check-control label { display: flex; align-items: center; gap: 6px; color: var(--ink-soft); font-size: 11px; }
.check-control input { width: 15px; height: 15px; accent-color: var(--signal); }
.active-filters { min-height: 26px; margin-top: 18px; display: flex; align-items: center; flex-wrap: wrap; gap: 7px; }
.active-label { margin-right: 4px; color: var(--muted); font-family: var(--mono); font-size: 10px; }
.no-filters { color: var(--muted-light); font-size: 11px; }
.filter-chip { min-height: 28px; padding: 5px 9px; display: inline-flex; align-items: center; gap: 8px; border: 1px solid #cac5b8; border-radius: 20px; background: #efebe1; color: var(--ink-soft); font-size: 10px; font-weight: 700; }
.filter-chip:hover { border-color: var(--signal); color: var(--signal); }
.filter-chip span { color: var(--signal); font-size: 15px; line-height: 10px; }
.filter-chip-time { border-color: #d6a477; background: #f8eadc; color: #9c5338; }

.workspace { margin-top: 26px; display: grid; grid-template-columns: minmax(0, 1.65fr) minmax(340px, 0.75fr); gap: 26px; align-items: start; }
.map-column { min-width: 0; display: flex; flex-direction: column; gap: 22px; }
.map-panel, .timeline-panel, .depth-panel, .stream-panel, .inspector { background: var(--surface); border: 1px solid var(--line); box-shadow: var(--shadow-soft); }
.map-panel { overflow: hidden; }
.panel-heading { min-height: 72px; padding: 20px 22px; display: flex; justify-content: space-between; align-items: center; gap: 16px; }
.panel-heading h2 { margin: 4px 0 0; font-family: var(--display); font-size: 25px; font-weight: 500; letter-spacing: -0.035em; line-height: 1; }
.map-heading-actions { display: flex; align-items: center; gap: 11px; }
.map-zoom { color: var(--muted); font-family: var(--mono); font-size: 10px; }
.icon-button { width: 38px; height: 38px; border: 1px solid var(--line); background: var(--surface-warm); color: var(--ink); font-size: 20px; }
.icon-button:hover { background: var(--dark); color: white; }
.map-frame { min-height: 500px; position: relative; background: #d9ded9; border-top: 1px solid var(--line); border-bottom: 1px solid var(--line); }
.map-container { width: 100%; height: 550px; z-index: 1; }
.map-key { position: absolute; z-index: 450; left: 14px; bottom: 14px; padding: 9px 11px; display: flex; flex-wrap: wrap; gap: 8px 13px; background: rgba(250, 248, 241, 0.94); border: 1px solid rgba(23, 37, 42, 0.16); color: var(--ink-soft); font-size: 10px; box-shadow: 0 5px 16px rgba(23, 37, 42, 0.1); }
.map-key span { display: inline-flex; align-items: center; gap: 5px; }
.key-swatch { width: 10px; height: 10px; display: inline-block; border-radius: 50%; }
.key-low { background: var(--teal); }
.key-high { width: 15px; height: 15px; background: var(--signal); }
.key-outline { width: 13px; height: 10px; display: inline-block; border: 2px dashed var(--dark); border-radius: 50%; }
.map-caption { min-height: 38px; padding: 9px 16px; display: flex; justify-content: space-between; gap: 14px; color: var(--muted); font-size: 10px; }
.map-attribution { color: var(--muted-light); white-space: nowrap; }
.map-loading, .map-error, .map-empty { position: absolute; z-index: 500; left: 50%; top: 50%; transform: translate(-50%, -50%); box-shadow: var(--shadow); }
.map-loading { width: min(340px, calc(100% - 30px)); padding: 13px 15px; display: flex; align-items: center; gap: 11px; background: rgba(26, 43, 46, 0.94); color: #f4f1e9; font-size: 12px; }
.loader-line { width: 24px; height: 3px; display: inline-block; background: var(--signal-bright); animation: pulse-line 1.15s ease-in-out infinite alternate; }
@keyframes pulse-line { from { transform: scaleX(0.45); transform-origin: left; } to { transform: scaleX(1); transform-origin: left; } }
.map-error { width: min(420px, calc(100% - 30px)); padding: 18px; display: grid; grid-template-columns: 1fr auto; gap: 5px 15px; background: #fff5e9; border: 1px solid #d7a276; color: var(--ink); }
.map-error strong { font-size: 13px; }
.map-error span { grid-column: 1 / -1; color: var(--muted); font-size: 11px; }
.map-error .button { grid-column: 2; grid-row: 1 / span 2; align-self: center; }
.map-empty { width: min(310px, calc(100% - 30px)); padding: 28px; display: flex; flex-direction: column; align-items: center; gap: 8px; text-align: center; background: rgba(250, 248, 241, 0.96); border: 1px solid var(--line); }
.empty-glyph { color: var(--signal); font-family: var(--display); font-size: 38px; line-height: 1; }
.map-empty strong, .inspector-empty h2 { font-family: var(--display); font-size: 23px; font-weight: 500; }
.map-empty span:not(.empty-glyph), .inspector-empty p { color: var(--muted); font-size: 11px; }
.map-empty .button { margin-top: 8px; }
.leaflet-container { font-family: var(--body); background: #d9ded9; }
.leaflet-control-zoom { border: 1px solid rgba(23, 37, 42, 0.18) !important; box-shadow: 0 4px 14px rgba(23, 37, 42, 0.1) !important; }
.leaflet-control-zoom a { width: 32px !important; height: 32px !important; line-height: 30px !important; color: var(--ink) !important; background: rgba(250, 248, 241, 0.95) !important; }
.leaflet-control-zoom a:hover { background: var(--dark) !important; color: white !important; }
.leaflet-control-attribution { background: rgba(250, 248, 241, 0.8) !important; color: var(--muted) !important; font-size: 8px !important; }
.leaflet-control-attribution a { color: var(--ink-soft) !important; }
.quake-cluster-icon { background: transparent; border: 0; }
.quake-cluster { width: 56px; height: 56px; display: flex; flex-direction: column; justify-content: center; align-items: center; border: 2px solid rgba(26, 43, 46, 0.72); border-radius: 50%; background: rgba(196, 111, 77, 0.82); color: white; box-shadow: 0 0 0 4px rgba(250, 248, 241, 0.65), 0 4px 12px rgba(23, 37, 42, 0.24); }
.quake-cluster b { font-family: var(--mono); font-size: 15px; line-height: 1; }
.quake-cluster small { margin-top: 3px; font-size: 9px; }
.quake-cluster-large { width: 64px; height: 64px; background: rgba(173, 64, 55, 0.9); }
.quake-marker-muted { opacity: 0.4; }

.timeline-panel { overflow: hidden; }
.timeline-heading { padding-bottom: 11px; }
.timeline-meta { display: flex; align-items: center; gap: 12px; color: var(--muted); font-size: 11px; text-align: right; }
.text-button { padding: 4px 0; background: transparent; color: var(--signal); font-size: 11px; font-weight: 800; }
.text-button:hover { text-decoration: underline; }
.timeline-chart-wrap { position: relative; padding: 0 15px 3px; border-top: 1px solid var(--line); }
.timeline-chart { width: 100%; height: auto; min-height: 175px; overflow: visible; }
.chart-baseline { stroke: #88938c; stroke-width: 1; }
.chart-gridline { stroke: #dedbd1; stroke-width: 1; stroke-dasharray: 3 4; }
.chart-axis-label, .chart-x-label { fill: var(--muted); font-family: var(--mono); font-size: 10px; }
.timeline-hit-area { fill: transparent; cursor: pointer; }
.timeline-hit-area:hover, .timeline-hit-area:focus-visible { fill: rgba(201, 87, 67, 0.1); outline: none; }
.timeline-hit-selected { fill: rgba(201, 87, 67, 0.12); }
.timeline-bar { fill: var(--teal); pointer-events: none; opacity: 0.86; }
.timeline-bar-selected { fill: var(--signal); }
.timeline-bar-empty { fill: #d3d7d1; opacity: 0.65; }
.timeline-cap { fill: var(--signal-bright); pointer-events: none; }
.timeline-focus-line { stroke: var(--ink); stroke-width: 1.5; stroke-dasharray: 4 4; pointer-events: none; }
.timeline-tooltip { position: absolute; top: 10px; min-width: 175px; padding: 8px 10px; transform: translateX(-50%); pointer-events: none; background: var(--dark); color: #f6f3eb; box-shadow: var(--shadow-soft); font-size: 10px; }
.timeline-tooltip b, .timeline-tooltip span { display: block; }
.timeline-tooltip b { color: #f4c88c; font-family: var(--mono); font-size: 10px; }
.timeline-tooltip span { margin-top: 3px; color: #ccd3cd; }
.timeline-reading { padding: 0 22px 17px; display: flex; flex-wrap: wrap; align-items: center; gap: 12px 20px; color: var(--muted); font-size: 10px; }
.timeline-reading-key { display: inline-flex; align-items: center; gap: 6px; }
.timeline-reading-key i { width: 12px; height: 8px; display: inline-block; border-radius: 2px; }
.timeline-key-volume { background: var(--teal); }
.timeline-key-peak { height: 4px !important; background: var(--signal-bright); }
.timeline-reading-note { margin-left: auto; color: var(--muted-light); }

.depth-panel { padding-bottom: 18px; }
.depth-panel .panel-heading { min-height: 62px; padding-bottom: 14px; }
.depth-distribution { padding: 0 22px; display: grid; grid-template-columns: repeat(4, 1fr); gap: 8px; }
.depth-band { min-width: 0; padding: 11px 10px; display: grid; grid-template-columns: 1fr auto; gap: 9px 7px; align-items: center; background: var(--surface-warm); border: 1px solid transparent; text-align: left; }
.depth-band:hover, .depth-band.is-active { background: #f7e8dd; border-color: #d7956f; }
.depth-band-copy b, .depth-band-copy small { display: block; }
.depth-band-copy b { font-size: 11px; }
.depth-band-copy small { margin-top: 2px; color: var(--muted); font-size: 9px; }
.depth-band > strong { color: var(--ink-soft); font-family: var(--mono); font-size: 11px; }
.depth-track { grid-column: 1 / -1; height: 6px; background: #d2d8d1; }
.depth-track i { height: 100%; display: block; min-width: 2px; background: var(--teal); }
.depth-band.is-active .depth-track i { background: var(--signal); }

.stream-panel { overflow: hidden; }
.stream-heading { min-height: 70px; }
.stream-total { text-align: right; }
.stream-total strong { display: block; font-family: var(--mono); font-size: 18px; font-weight: 500; }
.stream-total span { display: block; color: var(--muted); font-size: 10px; }
.stream-context { padding: 9px 22px; background: #f8e9de; border-top: 1px solid #e5c8b3; border-bottom: 1px solid #e5c8b3; color: #95573d; font-size: 11px; }
.event-list { border-top: 1px solid var(--line); }
.event-row { width: 100%; min-height: 74px; padding: 13px 22px; display: grid; grid-template-columns: 58px minmax(0, 1fr) auto 18px; align-items: center; gap: 14px; background: var(--surface); border-bottom: 1px solid var(--line); color: var(--ink); text-align: left; position: relative; }
.event-row:hover, .event-row:focus-visible { background: #f7f3e9; }
.event-row.is-selected { background: #f8e9de; box-shadow: inset 4px 0 0 var(--signal); }
.event-row.is-out-window:not(.is-selected) { opacity: 0.42; }
.event-row.is-in-window:not(.is-selected) { box-shadow: inset 3px 0 0 #daa16e; }
.event-magnitude { width: 50px; padding: 8px 5px; display: inline-flex; justify-content: center; background: #e8e4d9; color: var(--ink); font-family: var(--mono); font-size: 12px; font-weight: 500; }
.event-row.is-selected .event-magnitude { background: var(--signal); color: white; }
.event-row-main { min-width: 0; }
.event-row-main strong, .event-row-main span { display: block; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.event-row-main strong { font-size: 12px; font-weight: 800; }
.event-row-main span { margin-top: 5px; color: var(--muted); font-size: 10px; }
.event-row-tags { display: flex; justify-content: end; flex-wrap: wrap; gap: 5px; }
.tag { padding: 4px 6px; border-radius: 2px; color: var(--ink-soft); background: #e7ebe5; font-size: 9px; font-style: normal; font-weight: 800; white-space: nowrap; }
.tag-tsunami { background: #f5e3d2; color: #955438; }
.tag-reviewed { background: #e1ede5; color: #477362; }
.alert-green { background: #dcebe2; color: #477362; }
.alert-yellow { background: #f2e7c8; color: #88651f; }
.alert-orange { background: #f4ddd0; color: #9a4c35; }
.alert-red { background: #f1d1d0; color: #8d2929; }
.alert-unknown { background: #e8ebe7; color: var(--muted); }
.event-row-arrow { color: var(--signal); font-size: 12px; text-align: right; }
.load-more { width: calc(100% - 44px); min-height: 44px; margin: 16px 22px 8px; background: var(--surface-warm); color: var(--ink-soft); font-size: 11px; font-weight: 800; }
.load-more:hover { background: #e8e3d8; }
.load-more span { margin-left: 4px; color: var(--muted); font-weight: 500; }
.stream-empty { min-height: 150px; padding: 30px 22px; display: flex; flex-direction: column; align-items: flex-start; justify-content: center; gap: 7px; border-top: 1px solid var(--line); }
.stream-empty strong { font-family: var(--display); font-size: 21px; font-weight: 500; }
.stream-empty span { color: var(--muted); font-size: 11px; }
.stream-empty .button { margin-top: 7px; }
.stream-footnote { margin: 0; padding: 13px 22px 17px; color: var(--muted-light); font-size: 10px; }

.inspector { position: sticky; top: 18px; overflow: hidden; }
.inspector-topline { padding: 18px 22px 0; display: flex; justify-content: space-between; }
.dossier-index { color: var(--signal); font-family: var(--mono); font-size: 11px; }
.inspector-title-row { padding: 24px 22px 0; display: flex; justify-content: space-between; gap: 16px; align-items: start; }
.magnitude-hero { display: block; color: var(--signal); font-family: var(--mono); font-size: 41px; font-weight: 500; letter-spacing: -0.07em; line-height: 0.9; }
.inspector h2 { max-width: 320px; margin: 11px 0 0; font-family: var(--display); font-size: clamp(28px, 2.3vw, 38px); font-weight: 500; letter-spacing: -0.05em; line-height: 0.98; }
.status-seal { min-width: 74px; padding: 8px 7px; display: inline-flex; align-items: center; justify-content: center; gap: 5px; color: var(--muted); background: #e8ebe7; font-size: 9px; font-weight: 800; text-transform: uppercase; }
.status-seal i { width: 7px; height: 7px; display: inline-block; border-radius: 50%; background: currentColor; }
.status-seal.alert-green { background: #dcebe2; color: #477362; }
.status-seal.alert-yellow { background: #f2e7c8; color: #88651f; }
.status-seal.alert-orange { background: #f4ddd0; color: #9a4c35; }
.status-seal.alert-red { background: #f1d1d0; color: #8d2929; }
.detail-lede { margin: 14px 22px 0; color: var(--muted); font-size: 11px; line-height: 1.5; }
.detail-actions { padding: 19px 22px; display: flex; flex-wrap: wrap; gap: 8px; }
.detail-actions .button { flex: 1; min-width: 135px; }
.detail-grid { margin: 0; display: grid; grid-template-columns: 1fr 1fr; border-top: 1px solid var(--line); }
.detail-grid > div { min-width: 0; padding: 15px 17px; border-bottom: 1px solid var(--line); }
.detail-grid > div:nth-child(odd) { border-right: 1px solid var(--line); }
.detail-grid dt { color: var(--muted); font-family: var(--mono); font-size: 9px; letter-spacing: 0.04em; }
.detail-grid dd { margin: 5px 0 0; overflow: hidden; color: var(--ink); font-size: 12px; font-weight: 800; text-overflow: ellipsis; white-space: nowrap; }
.detail-grid small { display: block; margin-top: 3px; color: var(--muted-light); font-size: 9px; line-height: 1.35; }
.detail-note { margin: 18px 22px; padding: 12px; display: flex; gap: 10px; border-left: 2px solid var(--amber); background: #f2eee3; }
.note-symbol { width: 18px; height: 18px; flex: 0 0 18px; display: inline-flex; align-items: center; justify-content: center; border: 1px solid var(--amber); border-radius: 50%; color: #8d6b2a; font-family: var(--mono); font-size: 10px; }
.detail-note p { margin: 0; color: var(--ink-soft); font-size: 10px; line-height: 1.55; }
.detail-note strong { color: var(--ink); }
.detail-timestamp { padding: 13px 22px 18px; display: flex; flex-direction: column; gap: 3px; border-top: 1px solid var(--line); font-family: var(--mono); font-size: 9px; letter-spacing: 0; text-transform: none; }
.inspector-empty { min-height: 360px; padding: 55px 25px; display: flex; flex-direction: column; align-items: center; justify-content: center; text-align: center; }
.inspector-empty h2 { margin: 12px 0 0; }
.inspector-empty p { max-width: 220px; }

.footer { margin-top: 34px; padding: 32px 0 42px; display: grid; grid-template-columns: 1fr 1fr auto; gap: 30px; border-top: 1px solid var(--line-strong); color: var(--muted); }
.footer .brand-name { color: var(--ink); }
.footer p { max-width: 400px; margin: 9px 0 0; font-size: 11px; line-height: 1.55; }
.footer-method { max-width: 440px; }
.footer-mark { color: var(--signal); font-family: var(--display); font-size: 36px; align-self: center; }

@media (max-width: 1120px) {
  .topnav { display: none; }
  .filter-grid { grid-template-columns: repeat(3, 1fr); }
  .workspace { grid-template-columns: minmax(0, 1.4fr) minmax(310px, 0.8fr); }
  .summary-legend { justify-content: start; }
}

@media (max-width: 900px) {
  .topbar { padding-inline: 20px; }
  .top-actions { margin-left: auto; }
  .top-actions .connection-status { display: none; }
  .intro-band { padding-top: 50px; flex-direction: column; align-items: flex-start; }
  .intro-note { max-width: 380px; }
  .signal-summary { grid-template-columns: 0.7fr 1px 1.3fr; }
  .summary-legend { display: none; }
  .workspace { grid-template-columns: 1fr; }
  .inspector { position: static; grid-row: 2; }
  .map-column { grid-row: 1; }
  .map-container { height: 500px; }
  .depth-distribution { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 640px) {
  body { font-size: 13px; }
  .topbar { min-height: 67px; padding: 12px 15px; gap: 10px; }
  .brand-caption { display: none; }
  .brand-name { font-size: 10px; }
  .brand-mark { width: 23px; height: 29px; }
  .top-actions .button { padding-inline: 10px; }
  .intro-band, .signal-summary, .control-deck, .workspace, .footer { width: min(100% - 24px, 1440px); }
  .intro-band { padding-top: 39px; padding-bottom: 26px; gap: 26px; }
  .intro-band h1 { font-size: clamp(42px, 15vw, 66px); }
  .intro-copy { font-size: 14px; }
  .intro-note { padding-left: 13px; }
  .signal-summary { min-height: 0; padding: 18px 16px; grid-template-columns: 1fr; gap: 15px; }
  .summary-divider { width: 100%; height: 1px; }
  .summary-count strong { font-size: 50px; }
  .control-deck { margin-top: 17px; padding: 17px 14px 14px; }
  .time-rail { display: block; }
  .time-rail .control-label { display: block; margin-bottom: 9px; }
  .segmented-control { overflow-x: auto; }
  .segmented-control button { min-width: 94px; padding-inline: 8px; flex: 0 0 auto; }
  .segmented-control button span { font-size: 11px; }
  .control-actions { margin-top: 14px; justify-content: space-between; }
  .control-actions .button-light { margin-right: 0; }
  .filter-grid { grid-template-columns: 1fr 1fr; gap: 17px 12px; }
  .magnitude-filter, .place-search { grid-column: 1 / -1; }
  .active-filters { align-items: flex-start; }
  .workspace { margin-top: 17px; gap: 17px; }
  .map-column { gap: 17px; }
  .panel-heading { min-height: 65px; padding: 17px 15px; }
  .panel-heading h2 { font-size: 23px; }
  .map-heading-actions { gap: 7px; }
  .map-zoom { display: none; }
  .map-frame { min-height: 430px; }
  .map-container { height: 430px; }
  .map-key { left: 8px; right: 8px; bottom: 8px; gap: 6px 10px; }
  .map-caption { padding: 8px 12px; flex-direction: column; gap: 4px; }
  .map-attribution { white-space: normal; }
  .timeline-heading { display: block; }
  .timeline-meta { margin-top: 10px; text-align: left; }
  .timeline-chart-wrap { padding-inline: 6px; }
  .timeline-reading { padding-inline: 15px; gap: 9px 14px; }
  .timeline-reading-note { width: 100%; margin-left: 0; }
  .depth-distribution { padding-inline: 15px; gap: 7px; }
  .depth-band { padding: 10px 8px; }
  .stream-heading { padding-inline: 15px; }
  .stream-context { padding-inline: 15px; }
  .event-row { padding-inline: 15px; grid-template-columns: 52px minmax(0, 1fr) 14px; gap: 10px; }
  .event-row-tags { grid-column: 2 / 3; justify-content: start; }
  .event-row-arrow { grid-column: 3; grid-row: 1 / span 2; }
  .event-magnitude { width: 47px; }
  .stream-footnote { padding-inline: 15px; }
  .inspector-title-row { padding-inline: 17px; }
  .inspector-topline { padding-inline: 17px; }
  .detail-lede, .detail-actions, .detail-note, .detail-timestamp { margin-left: 17px; margin-right: 17px; }
  .detail-actions { padding-inline: 0; }
  .detail-grid > div { padding: 13px 12px; }
  .detail-grid dd { font-size: 11px; }
  .footer { grid-template-columns: 1fr; gap: 20px; padding-bottom: 30px; }
  .footer-mark { display: none; }
}

@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  *, *::before, *::after { animation-duration: 0.001ms !important; animation-iteration-count: 1 !important; transition-duration: 0.001ms !important; }
}

@media (forced-colors: active) {
  .event-row.is-selected, .event-row.is-in-window:not(.is-selected) { outline: 2px solid CanvasText; box-shadow: none; }
  .timeline-bar, .timeline-cap, .depth-track i { forced-color-adjust: none; background: Highlight; }
  .button, .filter-chip, .depth-band { border: 1px solid ButtonText; }
}

