:root {
  --ink: #17252a;
  --ink-soft: #314044;
  --muted: #687370;
  --muted-light: #89928c;
  --paper: #f4f1e9;
  --paper-deep: #e9e5db;
  --surface: #fbf9f3;
  --surface-warm: #f0ede4;
  --line: #d3d0c6;
  --line-strong: #aeb5ad;
  --dark: #1a2b2e;
  --dark-soft: #284247;
  --signal: #c95743;
  --signal-bright: #dd7454;
  --amber: #b7924f;
  --teal: #6c918b;
  --good: #5d8678;
  --warning: #bd8b34;
  --serious: #bb643d;
