                <label><span>To</span><input type="number" min="0" max={MAX_DEPTH} value={depthMax === MAX_DEPTH ? '' : depthMax} placeholder="700+" onChange={(event) => setDepthMax(Math.min(MAX_DEPTH, Math.max(depthMin, Number(event.target.value) || MAX_DEPTH)))} /></label>
