                  <line x1="42" x2="974" y1="148" y2="148" className="chart-baseline" />
                  <line x1="42" x2="974" y1="96" y2="96" className="chart-gridline" />
                  <line x1="42" x2="974" y1="44" y2="44" className="chart-gridline" />
